quests[40897] = { id = 40897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garvrulg" }
quests[40898] = { id = 40898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frischfleisch", description = "Dieser Krater wimmelt nur so von Teufelsfeuerbasilisken.\n\nSie sind vielleicht nicht die Schlauesten, aber sie sind ebenso hinterhältig und gefährlich wie alle Dämonen.\n\nAllerdings können sie uns trotzdem nützlich sein. Tötet die Basilisken und bringt mir ein paar Stücke ihres teufelsverderbten Fleisches.\n\nIch habe mit dem frischen Fleisch etwas Besonderes vor...", sourceObjective = "Sammelt 6 Stücke frisches Teufelsfleisch.", progress = "Habt Ihr das frische Teufelsfleisch für mich?", completion = "Ich sehe, dass Ihr Fleisch von frisch erlegten Teufelsbasilisken mitgebracht habt.\n\nHört gut zu, denn jetzt erkläre ich Euch, wozu das gut ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[40900] = { id = 40900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schwere Bürde", description = "Durch Eure Hilfe im Kampf gegen die Dunklen Reiter habt Ihr dem Licht Ehre erwiesen. Wir hängen vielleicht nicht demselben Glauben an, aber wir haben ein gemeinsames Ziel.\n\nAuf jeden Fall bin ich Euch dankbar, dass Euer Handeln mir ermöglicht, die Artefakte ihren rechtmäßigen Besitzern zurückzugeben. Und ich bin überzeugt, dass die Sichel von Elune bei Euch in den denkbar besten Händen ist.\n\nMöge sie Euch im Kampf gegen die Legion gute Dienste leisten, {name}.", sourceObjective = "Kehrt zu Erzdruide Großhuf im Hain der Träume zurück. Ihr könnt 'Traumwanderung' benutzen, um über den Smaragdgrünen Traumpfad zu reisen.", completion = "Die Sichel von Elune!\n\nIch hätte nie gedacht, dass sie jemand im Kampf führen könnte, ohne sich selbst in eine wilde Bestie zu verwandeln. Aber Ihr scheint ihre wilde Natur gezähmt zu haben.\n\nElune hat ganz sicher Eure Hand im Kampf geführt, {name}. Ihr habt erreicht, was zuvor noch keinem Druiden gelungen ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[40901] = { id = 40901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmschwinge die Verschlingerin", description = "Danke, dass Ihr mich aus der Gefangenschaft befreit habt, {class}.\n\nAllerdings ist Azoran kein gewöhnlicher Dämon, sondern ein mächtiger Eredar, der einen hohen Rang in der Brennenden Legion einnimmt.\n\nWenn Ihr mich weiterhin begleiten wollt, benötige ich einen Beweis Eurer Stärke.\n\nGrimmschwinge die Verschlingerin ist die Stärkste unter den Teufelsfledermäusen und damit eine geeignete Prüfung für Euch. Platziert das Basiliskenfleisch auf dem Altar im Norden und tötet Grimmschwinge, wenn sie auftaucht.\n\nWenn Ihr mir ihren Kopf bringt, werde ich nicht mehr an Euren Fähigkeiten zweifeln.", sourceObjective = "Tötet Grimmschwinge die Verschlingerin.", progress = "Was bringt Ihr für Neuigkeiten über Grimmschwinge die Verschlingerin?", completion = "Grimmschwinge war eine furchterregende Dämonin... Ich muss sagen, dass mich Eure Fähigkeiten beeindruckt haben, {name}.\n\nEs gibt hier noch sehr viel mehr Dämonen zu töten. Es ist gut, jemanden mit solchen Fähigkeiten an meiner Seite zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40902] = { id = 40902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Treasure 002 - Fel Breach - AJB" }
quests[40904] = { id = 40904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten des Entweihers", description = "Im Inneren dieses beunruhigenden Objekts seht Ihr eine wirbelnde blutrote Energie, deren Form sich bei jedem erneuten Blick darauf zu verändern scheint.\n\nSeine Macht ist völlig fremdartig und anders als alles, was Ihr in Draenor oder bei Euren Kämpfen mit der Legion je gesehen habt. Womöglich können Euch die Hüter der Mondlichtung in Azeroth mehr darüber sagen.", sourceObjective = "Holt Rat bei den Hütern der Mondlichtung ein. Womöglich wissen sie mehr über das Relikt des Chaos.", progress = "Ich hörte von Euren Heldentaten jenseits des roten Portals, {name}. Zwei Welten schulden Euch und Euren Mitstreitern ihren Dank. Was führt Euch zur Mondlichtung?", completion = "Wo... wo habt Ihr das gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[40905] = { id = 40905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant Strathmar" }
quests[40906] = { id = 40906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangen aus der Tiefe", description = "Seid gegrüßt, {class}.\n\nMein Heimatdorf, Jandvik, wird von einer Gruppe Naga belagert, die sich die Sashj'tar nennen.\n\nNormalerweise würde ich Fremde nicht um Hilfe bitten, aber gegen diesen Feind haben wir allein keine Chance.\n\nIn den Ruinen um Jandvik herum kann man viele Elfenrelikte finden. Wenn Ihr uns helft, ist Euch eine angemessene Belohnung gewiss.\n\nHaben wir also eine Abmachung?", sourceObjective = "Sprecht mit Toryl außerhalb von Jandvik.", sourceObjectiveStatus = "unverified-source-field" }
quests[40907] = { id = 40907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hindernisse aus dem Weg räumen", description = "{class}! Wollt Ihr Euch nicht ein paar Münzen verdienen?\n\nDer Jarl von Jandvik ist verschwunden und zwei dreiste Emporkömmlinge wollen jetzt die Herrschaft an sich reißen. Aber ich sollte der nächste Jarl sein, nicht sie!\n\nIch möchte, dass Ihr Euch nach Jandvik begebt und Calder und Eynar in einem Kampf auf Leben und Tod besiegt.\n\nIch traue normalerweise keinen Fremden, aber in dieser Situation benötige ich die Hilfe von jemandem wie Euch. Wenn ich meine Rivalen selbst töte, würden mich die Leute in Jandvik dafür verurteilen.\n\nTrefft mich im Zentrum von Jandvik, wenn Ihr den Auftrag ausgeführt habt.", sourceObjective = "Tötet Calder und Eynar in Jandvik.", completion = "Ohne meine Rivalen kann ich jetzt widerstandslos in Jandvik herrschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40908] = { id = 40908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Jarl auf der Spur", description = "Es scheint Euch zu gefallen, meinen Befehlen zu gehorchen, {name}. Vielleicht könnt Ihr mir weiter von Nutzen sein.\n\nJarl Throndyr, der Anführer von Jandvik, ist schon eine Zeit lang verschollen. Ich vermute, dass er im Kampf gegen die Nagaeindringlinge der Sashj'tar gefallen ist, aber ich muss es mit Sicherheit wissen.\n\nFindet heraus, was mit ihm geschehen ist.\n\nWenn Ihr dies für mich erledigt, versichere ich Euch, dass meine Vrykul Euch nichts tun werden.", sourceObjective = "Sucht nach Jarl Throndyr in der Azurwindbucht.", completion = "<Throndyr atmet angestrengt und murmelt ein paar Worte.>\n\nGift... fließt durch... meinen Körper.", sourceObjectiveStatus = "unverified-source-field" }
quests[40909] = { id = 40909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 DH-VotW - Small Treasure Chest 000" }
