quests[40918] = { id = 40918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rabenwehr - Quest mit heroischer Belohnung" }
quests[40919] = { id = 40919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsflederleder", description = "Ah, <mein treuer Gehilfe/meine treue Gehilfin>. Ich habe mal wieder eine ideale Aufgabe für Euch.\n\nIhr habt sicher schon bemerkt, dass Teufelskraft in lebendes Gewebe einsickert und leicht wieder daraus extrahiert werden kann.\n\nAußerdem treiben mich diese Fledermäuse in den Wahnsinn. Also könnten wir doch zwei Fledermäuse mit einer Klappe schlagen. Oder eher mit einer Klinge. Und zwar mit Eurer.\n\nNehmt diesen Kristall. Damit könnt Ihr diese Biester vom Himmel holen und direkt vor Eure Füße fallen lassen.\n\nWenn Ihr schon dabei seid, könnt Ihr mir ja auch gleich ihre Häute bringen, damit dieser Kerl in der Ecke eine Weile lang Ruhe gibt.", sourceObjective = "Sammelt 50 Teufelsfledermaushautfetzen für Kyrtos.", progress = "Habt Ihr die Häute schon?", completion = "Ich höre ihr Kreischen nicht mehr. Endlich Ruhe und Frieden!", sourceObjectiveStatus = "unverified-source-field" }
quests[40920] = { id = 40920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinbinderprämie" }
