quests[40925] = { id = 40925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einbruch in die Beißsteinenklave" }
quests[40927] = { id = 40927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jandviks letzte Hoffnung", description = "Kommandant Malt'his hat sich mit einem Meeresriesen beratschlagt?\n\nOhne Eure Hilfe würde dieses Dorf ganz sicher den vereinten Kräften der Sashj'tar und der Meeresriesen zum Opfer fallen.\n\n<Toryl steht einen Augenblick lang ganz ruhig da.>\n\nTrefft mich in einer der unterirdischen Höhlen draußen in der Azurwindbucht.\n\nIch möchte Euch etwas zeigen, das die Schlacht zu unseren Gunsten wenden könnte.", sourceObjective = "Trefft Euch mit Toryl in der Grotte der Sashj'tar.", completion = "Ich weiß nicht, wer Ihr seid, aber ich möchte Euch danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[40929] = { id = 40929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht", description = "Dieser Dämon verfügt über Informationen, die uns zu den Anführern führen könnten.\n\nLeider hat er mehr Angst vor seinem Meister als vor uns. Das müssen wir ändern.\n\nDie mächtigsten Soldaten der Brennenden Legion tragen oftmals Symbole bei sich, die ihren Rang und Status innerhalb der Dämonenarmee repräsentieren.\n\nSucht nach den stärksten Dämonen in der Teufelsseelenbastion, tötet sie und kommt mit ihren Emblemen zu mir zurück.\n\nSo werden wir diesem Wyrmzungendiener schon zeigen, wen er wirklich zu fürchten hat...", sourceObjective = "Sammelt 8 Embleme der Legion.", progress = "Habt Ihr die Embleme der Legion?", completion = "Wie ich sehe, habt Ihr die Embleme. Ausgezeichnet.\n\nMal sehen, wie unser Wyrmzungenfreund hier reagiert, wenn er sieht, was wir mit seinen Kameraden angestellt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[40930] = { id = 40930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apokalypse", description = "<Die Stimme des Lichkönigs durchdringt erneut Euren Verstand.>\n\nEs existiert ein uraltes Schwert, das im Widerhall der Zeiten verloren gegangen ist und die Macht hat, meine Rache über die Legion zu bringen.\n\nEs ist als Apokalypse bekannt.\n\nIch spüre, dass die Klinge sich in den Händen der Dunklen Reiter vom Gebirgspass der Totenwinde befindet. Ihre Magie verbirgt sie vor meinen Augen, aber sie können sich nicht vor der Geißel verstecken! Meine Agenten haben sie zuletzt am Anwesen der Dunstmantels gesehen.\n\n\nBegebt Euch dorthin, {name}. Besiegt die Dunklen Reiter und holt Euch das Schwert!", sourceObjective = "Beginnt Eure Suche nach Apokalypse am Anwesen der Dunstmantels in Dämmerwald.", progress = "Und warum genau sollte ich Euch helfen, {class}?", completion = "Ich habe kaum eine andere Wahl. Einen weiteren Angriff der Dunklen Reiter würde ich nicht überstehen, und Ihr seid offensichtlich mit großer Kraft gesegnet.\n\nIch werde Euch helfen, Euer Artefakt zu finden. Aber im Gegenzug verlange ich, die anderen Artefakte ihren rechtmäßigen Besitzern zurückbringen zu dürfen.\n\nHaben wir also eine Abmachung, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[40931] = { id = 40931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Spuren des Fluchs", description = "Nun gut. Dann also der Reihe nach: Ich bin Revil Kost, ein Priester des Lichts auf der Suche nach verschollenen Artefakten. Ich habe schon einmal mit den Dunklen Reitern zu tun gehabt und bin zurückgekehrt, um diesen Ort von ihnen zu befreien.\n\nDie Reiter sind nicht leicht zu fassen, aber ich weiß vielleicht, wo wir einen Hinweis auf sie finden können. In einem unserer früheren Kämpfe konnte ich einen Blick auf ihre Vergangenheit erhaschen. Dank des Segens, den mir der Umhang der Reinheit gewährte, sah ich, wer die Dunklen Reiter früher waren.\n\nKommt mit mir in Aridens Lager. Ich werde Euch auf dem Weg alles erklären.", sourceObjective = "Begleitet Revil Kost vom Anwesen der Dunstmantels im Dämmerwald zu Aridens Lager am Gebirgspass der Totenwinde.", completion = "Eure Gesellschaft ist mir zwar unangenehm, aber Ihr seid ohne Frage ein mächtiger Verbündeter.\n\nIch glaube, dass hier irgendwo der Schlüssel zum Aufenthaltsort der Dunklen Reiter verborgen liegt. Es ist seltsam, dass die Reiter uns nicht hierher gefolgt sind. Wir sollten uns allerdings beeilen, bevor sie ihre Meinung ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[40932] = { id = 40932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unberührte Zeugen", description = "Hier hatte der Händler Ariden sein Lager aufgeschlagen, als er einst versuchte, seine dubiosen Waren dem Zauberer Medivh zu verkaufen.\n\nSeltsamerweise ist es über all diese Zeit hinweg relativ unberührt geblieben. Deswegen glaube ich, dass immer noch eine Verbindung zum vormaligen Besitzer bestehen könnte.\n\nHelft mir, das Lager zu durchsuchen. Vielleicht finden wir hier etwas, das uns zu den Dunklen Reitern führt.", sourceObjective = "Sucht Aridens Lager nach Hinweisen auf den Aufenthaltsort der Dunklen Reiter ab.", completion = "Das dunkle Energie verströmende Tagebuch scheint Ariden zu gehören und seine Zeit am Gebirgspass der Totenwinde zu beschreiben. Ein Eintrag ist besonders auffällig:\n\n\"Ich höre diese flüsternden Stimmen. Sie rufen mich aus dem nassen Boden hastig ausgehobener Gräber und berufen sich auf mein Erbe.\n\nAber welches Erbe meinen sie? Der Händler, der ich einst war, entstammte keiner besonderen Blutlinie...\n\nWie dem auch sei, sie ruft mich zu sich. Die Schreckensklinge... der Weltenender... Apokalypse.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[40933] = { id = 40933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine grausame Aufgabe", description = "Nasser Boden? Hastig ausgehobene Gräber?\n\nIch glaube, im Tagebuch ist von den Gräbern am See nahe Karazhan die Rede. Niemand weiß, wer dort begraben liegt, aber vielleicht sind sie der Schlüssel zum Aufenthaltsort der Dunklen Reiter.\n\nIhr... Ihr könnt doch mit den Toten sprechen, nicht wahr?", sourceObjective = "Scheucht die Toten in den hastig ausgehobenen Gräbern am Gebirgspass der Totenwinde auf, bis Ihr einen findet, der Euch den Aufenthaltsort der Dunklen Reiter verrät.", completion = "Das frostige Gefühl, das ich verspüre, sagt mir, dass Ihr erfolgreich wart.\n\nWas habt Ihr herausgefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[40934] = { id = 40934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunklen Reiter", description = "Die Katakomben? Von so einem Ort habe ich noch nie gehört. Es sei denn, er meint...\n\nAm Flussufer findet sich ein Kanalisationsgitter, über das man in die Tunnel gelangen kann, die unterhalb von Karazhan verlaufen. Ich habe es nie beachtet, aber womöglich führt es ja zu den Katakomben, von denen der Geist sprach.\n\nVielleicht haben sich die Dunklen Reiter ja die ganze Zeit direkt unter unseren Füßen aufgehalten! Kommt, lasst uns schauen, wo uns das hinführt.", sourceObjective = "Besiegt die Dunklen Reiter in den Katakomben von Karazhan und nehmt Apokalypse an Euch.", completion = "Heute haben wir den Dunklen Reitern einen schweren Schlag versetzt und einen Sieg für die Bewohner des Dämmerwalds errungen.\n\nSie stehen genauso in Eurer Schuld wie ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[40935] = { id = 40935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Rache", description = "Ich hatte mich in Euch getäuscht, Todesritter. Durch Eure Hilfe im Kampf gegen die Dunklen Reiter habt Ihr dem Licht Ehre erwiesen. Vielleicht sollte ich weniger vorschnell urteilen.\n\nAuf jeden Fall konnte ich dank Eurer Hilfe die Artefakte ihren rechtmäßigen Besitzern zurückgeben. Und ich denke, dass Apokalypse bei Euch in den denkbar besten Händen ist.\n\nMöge es Euch im Kampf gegen die Legion gute Dienste erweisen, Todesritter.", sourceObjective = "Nehmt das Schwarze Tor zum Frostthron und empfangt das Mal des Lichkönigs.", completion = "Der Champion des Lichkönigs kehrt zurück und führt eine mächtige Waffe für den Kampf gegen unsere Dämonenfeinde bei sich!\n\nMöge die Brennende Legion angesichts unserer Macht erzittern!", sourceObjectiveStatus = "unverified-source-field" }
quests[40936] = { id = 40936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Revil Convinced" }
quests[40937] = { id = 40937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Revil Defeated" }
quests[40938] = { id = 40938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht und die Leere", description = "Alonsus Faol ist ein wertvoller Verbündeter und seine Instinkte hinsichtlich Eurer Person haben sich als korrekt erwiesen. Ich glaube, Ihr seid perfekt geeignet, um bei einer Sache behilflich zu sein, die dieser Welt einen großen Dienst erweisen wird.\n\nIch möchte, dass Ihr an einem Ort fern von Azeroth eine Sache zu Ende bringt, die mein Volk vor langer Zeit begonnen hat. Werdet Ihr uns helfen?", sourceObjective = "Helft Velen bei seiner mysteriösen Aufgabe.", completion = "Willkommen zurück, Kardinal. Ihr werdet feststellen, dass wir alles so gut wie möglich für Euch vorbereitet haben. Wir sollten unverzüglich anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40939] = { id = 40939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Stormwing Matriarch" }
quests[40941] = { id = 40941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht: Angriff auf die Grube", description = "Die Schwarzfelsstreitkräfte aus der Grube in Gorgrond bilden einen Großteil der Armee der Eisernen Horde. Wenn wir sie an ihrem Heimatort ausmerzen, wird der Rest der Eisernen Horde kaum eine Chance haben, gegen uns zu bestehen.\n\nWenn Ihr diesen Kampf ausfechten wollt, dann bringt einige Freunde mit. Die Schwarzfelsorcs sind nicht so einfach zu besiegen.", sourceObjective = "Greift die Schwarzfelstruppen in der Grube in Gorgrond an.", completion = "Ich hab schon vom Angriff gehört, Scheff. Und auch von der Beute.\n\nEuch darf man nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40942] = { id = 40942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht: Angriff auf die Grube", description = "Die Schwarzfelsstreitkräfte aus der Grube in Gorgrond bilden einen Großteil der Armee der Eisernen Horde. Wenn wir sie an ihrem Heimatort ausmerzen, wird der Rest der Eisernen Horde kaum eine Chance haben, gegen uns zu bestehen.\n\nWenn Ihr diesen Kampf ausfechten wollt, dann bringt einige Freunde mit. Die Schwarzfelsorcs sind nicht so einfach zu besiegen.", sourceObjective = "Greift die Schwarzfelsorcs in der Grube in Gorgrond an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, der Herr, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[40943] = { id = 40943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht: Angriff auf das Herz von Shattrath", description = "Truppen der Sargerei aus dem Inneren Shattraths werden mit jedem Tag stärker und wagemutiger. Sie stellen ein Risiko dar, das wir nicht länger ignorieren können.\n\nWenn Ihr Euch den Sargerei im Herzen der Stadt stellen wollt, solltet Ihr Verbündete mitbringen.", sourceObjective = "Greift die Sargereitruppen in Shattrath in Talador an.", completion = "Ich hab schon vom Angriff gehört, Scheff. Und auch von der Beute.\n\nEuch darf man nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40944] = { id = 40944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht: Angriff auf das Herz von Shattrath", description = "Truppen der Sargerei aus dem Inneren Shattraths werden mit jedem Tag stärker und wagemutiger. Sie stellen ein Risiko dar, das wir nicht länger ignorieren können.\n\nWenn Ihr Euch den Sargerei im Herzen der Stadt stellen wollt, solltet Ihr Verbündete mitbringen.", sourceObjective = "Greift die Sargerei in Shattrath in Talador an.", completion = "Es machen bereits Nachrichten über den Angriff die Runde, genauso wie ein Teil der Kriegsbeute.\n\nGute Arbeit, der Herr, wenn ich so frei sein darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[40947] = { id = 40947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speziallieferung", description = "Verenes Kind wird vermisst. Ich weiß vermutlich, was passiert ist, doch ich muss mir sicher sein.\n\nDie meisten Wachen nutzen Kuriere zur Übermittlung sensibler Informationen. Die Nutzung von Magie ist nur den hochrangigen Beamten vorbehalten.\n\nNehmt diese Klinge. Berührt nicht die Schneide. Überfallt damit heimlich die Kuriere und beschafft ihre Nachrichten.\n\nMit etwas Glück werden wir darin auf den Aufenthaltsort des Mädchens stoßen.\n\nSchließlich wissen wir Wachen alles.\n\n<Ein gewinnendes Lächeln ziert Silgryns Gesicht.>", sourceObjective = "Besorgt mithilfe der Zauberklinge der Nachtgeborenen 3 Stapel Briefe von Kurieren der Nachtgeborenen.", progress = "Hattet Ihr Erfolg?", completion = "Gute Arbeit. Die werde ich jetzt durchlesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40949] = { id = 40949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht bis zur letzten Feder", description = "Ich habe Euch beobachtet. Ihr gehört nicht zu denen.\n\n<Ivanel hustet leise.>\n\nIch werde bald dahinscheiden, aber ich möchte Euch um eine Sache bitten, solange Ihr hier seid.\n\nDie Hippogryphen hier verteidigen immer noch erbittert ihr Zuhause und ihre Gefährten der Mondwache. Sie haben noch nicht akzeptiert, dass die Mondwache Vergangenheit ist.\n\nBitte... schickt sie weg. Sagt ihnen, dass es hier nichts mehr gibt, für das es sich zu kämpfen lohnt.", sourceObjective = "Schickt 5 Hippogryphen von Mondfall fort.", completion = "Danke. Jetzt, da ich weiß, dass sie sich nicht länger für uns opfern werden, geht es mir schon besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[40950] = { id = 40950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfolg würdigen", description = "Alles ist nach Plan verlaufen. Eure neuen Klingen sind ein Beweis dafür.\n\nWir werden keine andere Wahl haben, als Euch in den kommenden Wochen und Monaten eine Menge abzuverlangen. Es gehört sich aber durchaus, dass wir uns einen Moment Zeit nehmen und unseren Erfolg feiern.\n\nWas sagt Ihr dazu?", sourceObjective = "Feiert die erfolgreiche Beschaffung Eures Artefakts mit den anderen Schatten.", progress = "Es heißt töten oder getötet werden.", completion = "Ihr scheint einen wunden Punkt getroffen zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[40951] = { id = 40951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basar der Beißsteinenklave" }
quests[40952] = { id = 40952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Jägern", description = "Jetzt, wo Thas'dorah in Eurem Besitz ist, solltet Ihr etwas mehr über die Nachtelfe erfahren, der Ihr diese Reise zu verdanken habt.\n\nIch schlage vor, dass Ihr in den Laden \"Die Weiten des Jägers\" zurückkehrt, wo Ihr meinen Boten getroffen habt. Wer immer diese Emmarel Schattenwächter auch ist... sie scheint eine bedeutende Rolle im Krieg gegen die Legion einzunehmen.", sourceObjective = "Begebt Euch zum Laden \"Die Weiten des Jägers\" in Dalaran und sprecht dort mit Emmarel Schattenwächter.", completion = "Es gibt noch viel zu tun, edler {class}. Aber zuvor wollt Ihr sicher wissen, wer ich bin und warum ich an Euch herangetreten bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[40953] = { id = 40953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf des Adlers Schwingen", description = "Schon seit ewigen Zeiten hat mein Orden für den Fall, dass die Legion zurückkehren sollte, Wache über die Verheerten Inseln gehalten. Wir sind nur noch sehr wenige... aber das ändert sich heute.\n\nDas Artefakt in Eurer Hand ist mehr als nur eine Waffe. Es ist ein Symbol, unter dem sich die Jäger aller Königreiche und Glaubensrichtungen versammeln werden.\n\nIhr werdet sicherlich einige Fragen haben. Trefft mich bei der Volltrefferhütte am Hochberg, um mit eigenen Augen zu sehen, was uns erwartet. Schneefeder und ich werden eigenständig dort hinreisen.", sourceObjective = "Trefft Euch mit Emmarel Schattenwächter bei der Volltrefferhütte am Hochberg.", completion = "Ich habe Euch und Eure Fähigkeiten schon einige Zeit aus der Ferne beobachtet, {name}.\n\n\n\nMoment... Das klingt ja eher unheimlich... Verzeiht, ich bin Gesellschaft nicht mehr so gewohnt. Lasst es mich anders erklären.\n\nUnser Orden war auf der Suche nach Jägern, die den Unsichtbaren Pfad in ein neues Zeitalter führen könnten. Und dafür seid Ihr von allen am besten geeignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[40954] = { id = 40954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Unsichtbare Pfad", description = "Eintausend Jahre lang hat der Unsichtbare Pfad gewacht und gewartet. Es waren nur noch wenige von uns übrig, die im Hintergrund verborgen agierten, wenn Azeroth uns brauchte. Es wussten nur sehr wenige, dass unsere Gruppe überhaupt existierte.\n\nAber die Zeit des Abwartens in den Schatten ist vorbei.\n\nBevor wir uns an die Arbeit machen, sollt Ihr noch etwas mehr über den Unsichtbaren Pfad erfahren.", sourceObjective = "Hört Euch Emmarels Geschichte an.", completion = "Die Legion ist zurückgekehrt und der Unsichtbare Pfad braucht frisches Blut... eine neue Führung.\n\nDie Waffe in Eurer Hand belegt, dass niemand anderes besser dazu geeignet sein könnte als Ihr.\n\nWerdet Ihr die Führung übernehmen? Werdet Ihr den Eid erfüllen, den mein Orden vor so langer Zeit abgelegt hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[40955] = { id = 40955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treueeid", description = "Vor Euch versammelt seht Ihr viele der größten Bogenschützen, Waldläufer, Bestienmeister und Fallensteller dieser Welt. Sie alle sind bereit, gemeinsam gegen die Legion zu kämpfen.\n\nJetzt ist es an der Zeit, dass Ihr den ersten Schritt als <wahrer Anführer/wahre Anführerin> der Jäger unternehmt.\n\nWir treffen uns an der Feuerstelle und legen vor der Statue von Ohn'ahra unseren Treueeid ab. Berührt die Statue und kniet vor ihr nieder, während ich den Eid rezitiere. Dadurch besiegelt Ihr die Wiedergeburt des Unsichtbaren Pfades!", sourceObjective = "Kniet vor der Adlerstatue nieder und legt Euren Treueeid gegenüber dem Unsichtbaren Pfad ab.", progress = "Ohn'ahra hat unseren Orden gesegnet!", completion = "Ohn'ahra ist uns seit der Gründung des Ordens nicht mehr erschienen!\n\nDas ist mit Sicherheit ein Zeichen, dass der Unsichtbare Pfad unter Eurer Führung über die Legion triumphieren wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[40956] = { id = 40956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer dem Leitstrahl nach...", description = "Wir sollten jetzt die erste sichere Verbindung unseres Teleportationsnetzwerkes einrichten.\n\nNehmt diesen Signalgeber mit zu den Ruinen von Elune'eth über uns und sucht gründlich die Gegend ab, um einen geeigneten Ort für ihn zu finden.\n\nWenn die Untersuchung beendet ist, platziert Ihr einfach den Signalgeber an der Stelle, damit ich von hier aus eine Verbindung zu ihm herstellen kann.", sourceObjective = "Verwendet den telemantischen Signalgeber, um die Ruinen von Elune'eth zu untersuchen.", completion = "<Dies scheint ein guter Platz für den Teleporter zu sein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40957] = { id = 40957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine starke rechte Hand", sourceObjective = "Ungeachtet der Unterstützung durch die anderen {class} wird der Kreuzzug gegen die Legion einen Großteil Eurer Zeit und Aufmerksamkeit beanspruchen. Dies ist ein Krieg, den Ihr nicht allein führen könnt.\n\nFrüher diente ich zunächst der Gründerin unseres Ordens, Namuria Hainsang, indem ich als ihre Augen und Ohren fungierte, während sie an anderer Stelle gefordert war. Es wäre mir eine Ehre, Euch ebenfalls auf diese Weise zu dienen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40958] = { id = 40958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktische Angelegenheiten", description = "Jetzt, wo Euer Artefakt bereit ist, wird es Zeit, Euren ersten Schlag gegen die Legion zu planen.\n\nSprecht mit Taktikerin Zunderschlag, unserer Expertin in solchen Angelegenheiten.", sourceObjective = "Sprecht mit Taktikerin Zunderschlag in der Volltrefferhütte.", completion = "Seid gegrüßt, Spurensucher! Es wird mir eine Ehre sein, Euch im Kampf gegen die Legion zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40959] = { id = 40959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feldzug beginnt", description = "Die Legion glaubt, dass wir immer noch durch unsere Verluste an der Verheerten Küste geschwächt sind.\n\nWir werden ihnen das Gegenteil beweisen.\n\nUnsere Späher haben die Verheerten Inseln ausgekundschaftet und alles erfahren, was wir für unseren bevorstehenden Angriff wissen müssen.\n\nEs liegt an Euch, das erste Ziel festzulegen und den Angriff des Unsichtbaren Pfades persönlich anzuführen.", sourceObjective = "Wählt den ersten Angriffspunkt auf der Schlachtkarte aus.", completion = "Eine ausgezeichnete Wahl. Der Feldzug gegen die Legion hat begonnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40960] = { id = 40960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glitzernde Perle", description = "Auf Eurem Angelhaken balanciert eine Perle, wie Ihr sie noch nie gesehen habt. Sie strahlt eine kaltes, beständiges Licht aus und scheint ihre Größe und ihr Gewicht in Eurer Hand ständig zu ändern.\n\nDas ist ganz klar ein magischer Gegenstand, den sich jemand anschauen sollte, der sich damit auskennt.", sourceObjective = "Bringt die glitzernde Perle zu Erzmagier Khadgar in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Eine Perle, sagt Ihr? Dann will ich sie mir mal genauer ansehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[40961] = { id = 40961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Springbrunnen von Dalaran", description = "Die hat bei Euch also \"angebissen\", was? Aber ich... ich bin mir nicht sicher, wie ICH Euch damit weiterhelfen kann. Hier.\n\n<Khadgar tätschelt Euren Kopf.>\n\n\"Gut gemacht.\"\n\nUnd was die Perle betrifft... Sie scheint magisch zu sein, aber mehr weiß ich darüber auch nicht zu sagen. Vielleicht würde sie sich ganz hübsch im Springbrunnen von Dalaran machen?", sourceObjective = "Bringt die glitzernde Perle zum Springbrunnen von Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Sie ist WUNDERSCHÖN! So etwas habe ich noch nie gesehen!\n\nJa, natürlich, schmeißt sie ruhig in den Brunnen. Die Leute schmeißen ja eh alle möglichen Sachen da rein.\n\n<Die Perle leuchtet jetzt noch heller und bewegt sich zu einer Stelle oberhalb des Wassers.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40962] = { id = 40962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Wasser", description = "Kommt mit mir zum Ufer von Elune'ara. Das kristallklare Wasser dort kann selbst die schwärzeste Finsternis hinfortwaschen und die Wahrheit ans Licht bringen.", sourceObjective = "Begleitet Malfurion zum See von Elune'ara um die Wahrheit über das Relikt des Chaos ans Licht zu bringen.", progress = "Ja, {race}?", completion = "Malfurion ist in großer Eile aufgebrochen, doch er bat mich darum, Euch das vor Eurer Abreise zu geben. Ich danke Euch für alles, was Ihr für Azeroth getan habt – und für das, was Ihr womöglich noch tun werdet!", sourceObjectiveStatus = "unverified-source-field" }
quests[40963] = { id = 40963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wunderstoff", description = "Wir hätten es kommen sehen müssen. Meine Schwester ist tot, meine Freunde sind verwundet und wir werden wahrscheinlich hier sterben.\n\nIch will Rache.\n\n<Lyrea gibt Euch ein Fläschchen mit einer grünen Flüssigkeit.>\n\nWir können sie nicht schlagen, aber wir können die Festung gegen sie wenden.\n\nWilde Hippogryphen werden von dem Geruch in diesem Fläschchen angezogen. Wilde Hippogryphen sind bekanntermaßen auch sehr gewalttätig, wenn das Objekt ihrer Begierde kein Hippogryph ist.\n\nMacht Euch das zunutze, um einen Weg in die Tiefen der Festung frei zu machen.", sourceObjective = "Lockt 3 wilde Hippogryphen von Mondfall an, damit sie sich der Nachtgeborenen am Mondfallhorst entledigen.", progress = "Ich dachte, ich wäre hier allein. Seid Ihr hier, um den Kampf fortzusetzen?", completion = "Ich hörte Schreie und war dankbar, dass diese von den Nachtgeborenen stammten. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40964] = { id = 40964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So nah und doch so fern", description = "Ich war bei Lothrius, als die Nachtgeborenen in die Festung strömten.\n\nEr und seine Konstrukte schafften es, die meisten von uns aus dem Athenaeum herauszuschaffen, aber er wurde in die Ecke getrieben, bevor er sich um seine eigene Flucht kümmern konnte.\n\nIch weiß, dass er noch lebt. Das sagt mir mein Bauchgefühl! Aber ich kann nicht selbst zurückgehen und ihn holen. Meine Verletzungen sind zu schwer.\n\nWeidenschnabel wird Euch an den Ort bringen, wo wir Lothrius zuletzt gesehen haben. Lasst ihn einfach wissen, wenn Ihr aufbruchbereit seid.\n\nGeht, rasch, und viel Glück!", sourceObjective = "Sucht nach Lothrius Mondrufer im Athenaeum.", completion = "Serena hat Euch geschickt? Gut... Sie lebt noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[40965] = { id = 40965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Tretmine zum bösen Spiel", description = "Sie haben meine Bibliothek geplündert, {name}.\n\nWenn sie unser Wissen wollen, dann sollen sie es bekommen.\n\nMit dieser Rune könnt Ihr einen Fesselungszauber auf dem Boden platzieren. Wenn die Nachtgeborenen in den Bereich hineinlaufen, werden sie die wahre Macht der Mondwache schon kennenlernen.\n\nSorgt dafür, dass sie ihre Lektion lernen!", sourceObjective = "Tötet 50 Nachtgeborene mit der Fallenrune.", progress = "Wie läuft der Unterricht?", completion = "Diese Lektion müssen wir alle irgendwann lernen: Geht niemals davon aus, dass der Feind tot ist, bevor Ihr nicht die Leiche gesehen habt. <Lothrius grinst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40966] = { id = 40966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualisten sind unter uns" }
quests[40967] = { id = 40967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was uns noch bleibt", description = "Ich konnte den Schutz dieser Mauern nicht verlassen und mich selbst auf die Suche begeben, aber es gibt drei Folianten, die für mich und die meinen von größter Bedeutung sind.\n\nSie enthalten Geheimnisse und Kniffe, von denen die Nachtgeborenen NIEMALS erfahren dürfen.\n\n<Lothrius legt Euch seine Hand auf die Stirn und brennt so die Namen der drei Folianten in Euer Gedächtnis ein.>\n\nWenn wir sie nicht besiegen können, müssen wir alles schützen, was uns teuer ist. Beeilt Euch, {name}.", sourceObjective = "Findet und beschafft die Folianten \"Anthologie der Wache\", \"Magisches Manifest des Mondes\" und \"Auswirkungen der Zerschlagung\".", progress = "Habt Ihr sie gefunden?", completion = "Der Mutter Mond sei Dank... Sie haben es überlebt!", sourceObjectiveStatus = "unverified-source-field" }
quests[40968] = { id = 40968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederholen, was gestohlen", description = "Meine Verletzungen werden mich zwar nicht umbringen, aber kämpfen kann ich auch nicht. Trotzdem weiß ich, wie wir mit den verbleibenden Nachtgeborenen fertigwerden.\n\nSie haben gleich nach ihrer Ankunft unsere Verteidigungsmatrix zerstört. Einer von ihnen wird ganz sicher noch den Zauberfokus bei sich tragen, den man zur Reaktivierung benötigt.\n\nBeschafft diesen Fokus und sucht Euch dann einen Hippogryphen. Ihr findet sie überall in der Festung.\n\nDiese treuen Tiere bringen Euch hinauf in den Himmel und kümmern sich um den Rest.", sourceObjective = "Besorgt einen instabilen Zauberfokus.", sourceObjectiveStatus = "unverified-source-field" }
quests[40969] = { id = 40969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sternwebers Schicksal", description = "Ich werde diese Folianten zu Thalrenus bringen.\n\nDa gibt es eine Sache, die mich sehr beschäftigt, und ich möchte, dass Ihr Euch an meiner Stelle darum kümmert.\n\nMeine Frau und Lebenspartnerin, Syrana Sternweber, lebt im Sternwebersanktum auf der anderen Seite der Brücke. Es wurde überrannt, als die Nachtgeborenen in die Festung eindrangen.\n\nWenn sie noch lebt, muss sie von unseren Bemühungen erfahren. Ihre Kraft wird hier dringend gebraucht.\n\nRichtet ihr bitte Grüße aus. Ich werde bald bei ihr sein.", sourceObjective = "Sucht nach Syrana Sternweber.", completion = "Lothrius und Thalrenus leben also noch. Vielleicht gibt es ja doch noch Hoffnung. Ich danke Euch, dass Ihr Euch auf die andere Seite der Brücke gewagt habt, Fremder.", sourceObjectiveStatus = "unverified-source-field" }
quests[40970] = { id = 40970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dirigent unseres Untergangs", description = "Wir müssen Beschwörer Thalerian aufhalten.\n\nEr hat sofort nach seiner Ankunft das private Studierzimmer meines Vaters aufgesucht und ist immer noch nicht wieder herausgekommen. Ich befürchte, dass er einen sehr gefährlichen Gegenstand gefunden hat.\n\nEr wird Schlüsselstein des Astromanten genannt. Mit ihm können die Verteidigungsanlagen der Festung manipuliert werden.\n\nSeine Magie ist für den Schutz der Mondwache gedacht. Nutzt man sie für einen anderen Zweck, kann sie unvorstellbare Zerstörungen bewirken.\n\nHolt den Schlüsselstein, auch wenn Ihr dazu Beschwörer Thalerian töten müsst.", sourceObjective = "Tötet Beschwörer Thalerian und nehmt ihm den Schlüsselstein des Astromanten ab.", progress = "Ist es vollbracht?", completion = "Sie hatten kein Anrecht auf diese Macht. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[40971] = { id = 40971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überwältigende Ablenkung", description = "Seht Ihr die Nachtgeborenen außerhalb dieses Raums?\n\nSie halten uns hier wie Mäuse in einem Käfig gefangen. Für sie ist es bequemer, wenn wir hier festsitzen, und sie das Sanktum nach den Relikten meines Vaters durchsuchen können.\n\nMit ein wenig Hilfe können ich und meine Gefährten zu einer höher gelegenen Ebene entkommen.\n\nNehmt diesen Kristall. Stellt Euch auf eine Mana fokussierende Rune und überladet dann mit ihm einen Beschwörer.\n\nDessen Beschwörungen werden sich gegen ihn richten und uns so etwas Freiraum verschaffen.\n\nNutzt dies weise. Wir werden uns auf der Spitze der Festung treffen, wenn der Weg frei ist.", sourceObjective = "Überladet 3 kaiserliche Beschwörer mit dem inaktiven Kristall. Um den Kristall nutzen zu können, müsst Ihr auf einem Manafokussierer stehen.", completion = "Dank Euch haben wir es sicher hierher geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[40972] = { id = 40972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Gefecht der Mondwache", description = "Das ist alles, was von der Mondwache übrig ist.\n\nSeht genau hin.\n\nWir sind nur noch ein Schatten unserer selbst, und unser Elend haben wir den Nachtgeborenen zu verdanken.\n\nIm Moment können wir nicht mehr tun. Wenn wir überleben wollen, müssen wir sofort verschwinden.\n\nDie Vergeltung kann warten.", sourceObjective = "Verlasst die Mondwachenfestung mit Thalrenus, Lothrius und Syrana.", completion = "Ich habe sie hierhergerufen. Ich möchte, dass man sich um sie kümmert, nachdem sie so viel Schreckliches durch mein Volk erleiden mussten.", sourceObjectiveStatus = "unverified-source-field" }
quests[40973] = { id = 40973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erschaffung von Zeit", description = "Vor allem dank Eures unermüdlichen Einsatzes haben wir herausgefunden, wo sich ein mächtiges Stück unserer Geschichte befindet. Damit können wir hoffentlich alles überleben, was die Nachtgeborenen uns entgegenschleudern, und vielleicht sogar mehr.\n\nDieses Stück zu bergen, wird uns aber ein großes Maß an Energie und Konzentration abverlangen. Wir werden versuchen, Sternwebers Enthüllungsritual zu unterstützen, aber schon die kleinste Störung würde diesen fragilen Zauber ruinieren. Sorgt bitte dafür, dass wir nicht gestört werden.\n\nSprecht mit Syrana Sternweber, wenn Ihr bereit seid.", sourceObjective = "Verteidigt Syrana Sternweber.", sourceObjectiveStatus = "unverified-source-field" }
quests[40974] = { id = 40974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Latosius' Prüfung", description = "Latosius' Weisheit ist unermesslich. Wenn wir überleben wollen, müsst Ihr das Amulett für Euch beanspruchen. Wenn Ihr diese Prüfung übersteht, {name}, werdet Ihr für alle Zeiten mit der Macht der Mondwache gesegnet sein.", sourceObjective = "Überlebt Latosius' Prüfung.", sourceObjectiveStatus = "unverified-source-field" }
quests[40975] = { id = 40975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arluin Bribe Tracking" }
quests[40976] = { id = 40976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audienz beim Kriegshäuptling", description = "Die Lage hier ist sehr angespannt, <Dämonenjäger/Dämonenjägerin>. Kriegshäuptling Vol'jin wurde bei dem fehlgeschlagenen Angriff auf die Verheerte Küste schwer verwundet.\n\nIch würde Euch empfehlen, der Horde unverzüglich Eure Dienste anzubieten, bevor man Eure Gegenwart hier... missversteht.\n\nHochfürst Saurfang befehligt die Verteidigung der Stadt. Er ist zwar nicht gut auf die Illidari zu sprechen, aber wird Euch wohl dennoch eine Chance geben, Euch zu beweisen.\n\nSprecht mit ihm, um das Passierrecht zur Feste Grommash zu bekommen.", sourceObjective = "Sprecht mit Hochfürst Saurfang.", completion = "Vol'jins Tod war Teil eines größeren Plans. Die Legion profitiert davon, wenn die Reihen ihrer Feinde von innen geschwächt werden. Die Dämonen schlagen immer dann zu, wenn ihre Feinde am verwundbarsten sind.\n\nWelche Probleme die Horde auch immer beschäftigen mögen, jetzt können sie uns nicht mehr ignorieren.\n\nUnsere Zeit ist gekommen, Illidari.", sourceObjectiveStatus = "unverified-source-field" }
quests[40978] = { id = 40978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böse Bären" }
quests[40980] = { id = 40980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiterbeulenpest" }
quests[40982] = { id = 40982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweites Gesicht", description = "Sylvanas könnte als Kriegshäuptling problematisch sein. Im vorherigen Leben war sie eine stolze Waldläuferin und vielen von uns gut bekannt. Aber seit sie der Geißel anheimfiel, trauen einige ihrer eigenen Verbündeten der Bansheekönigin nicht mehr.\n\nDie Legion schlägt beim ersten Anzeichen von Zwietracht zu.\n\nUnd gerade jetzt spüre ich, dass etwas nicht stimmt, {name}. Ich fürchte, dass der Schein trügt.\n\nSchnell! Verwendet Eure Geistersicht. Wir müssen wissen, ob Feinde unter uns weilen.", sourceObjective = "Verwendet Eure Fähigkeit 'Geistersicht'.", completion = "Es war ja klar, dass die Legion versuchen würde, das Begräbnis zu infiltrieren. Alle Anführer der Horde gleichzeitig an einem Ort... Da kann ja wirklich kein Dämon widerstehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40983] = { id = 40983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonen unter ihnen", description = "Unser Verdacht hat sich bewahrheitet, {name}! Die Dämonen dachten, sie könnten uns überrumpeln.\n\nSchnell! Zu den Waffen! Beschützt die Bansheekönigin!", sourceObjective = "Beschützt den Kriegshäuptling.", progress = "Dafür wurden wir geboren.", completion = "Dank Eurer Warnung haben wir einen vielleicht katastrophalen Verlust verhindern können. Und jetzt können wir uns an diesem Legionsabschaum rächen.\n\nIhr genießt jetzt meine Aufmerksamkeit, {class}... und vielleicht sogar meine Anerkennung.", sourceObjectiveStatus = "unverified-source-field" }
quests[40985] = { id = 40985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übergriff der Naga der Reifschuppen: Hochberg" }
quests[40986] = { id = 40986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunklen Reiter", description = "Die Katakomben? Von so einem Ort habe ich noch nie gehört. Es sei denn, er meint...\n\nAm Flussufer findet sich ein Kanalisationsgitter, über das man in die Tunnel gelangen kann, die unterhalb von Karazhan verlaufen. Ich habe es nie beachtet, aber womöglich führt es ja zu den Katakomben, von denen der Geist sprach.\n\nVielleicht haben sich die Dunklen Reiter ja die ganze Zeit direkt unter unseren Füßen aufgehalten! Kommt, lasst uns schauen, wo uns das hinführt.", sourceObjective = "Besiegt die Dunklen Reiter in den Katakomben von Karazhan und nehmt Apokalypse an Euch.", progress = "Habt Ihr gefunden, wonach Ihr sucht, {class}?", completion = "Ich muss zwar zugeben, dass ich all dies nicht alleine zustande gebracht hätte, aber ich werde auch die Verfehlungen des heutigen Tages nicht vergessen.\n\nIhr habt jetzt, was Ihr wolltet, {class}. Es ist an der Zeit, dass Ihr geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40987] = { id = 40987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Rache", description = "Wir haben beide unsere Ziele erreicht, Todesritter. Jetzt trennen sich unsere Wege und darüber bin ich sehr froh.\n\nKehrt zurück zu Euren dunklen Meistern. Unsere Angelegenheiten hier sind beendet.", sourceObjective = "Nehmt das Schwarze Tor zum Frostthron und empfangt das Mal des Lichkönigs.", completion = "Der Champion des Lichkönigs kehrt zurück und führt eine mächtige Waffe für den Kampf gegen unsere Dämonenfeinde bei sich!\n\nMöge die Brennende Legion angesichts unserer Macht erzittern!", sourceObjectiveStatus = "unverified-source-field" }
quests[40988] = { id = 40988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu viele Köche", description = "Seid gegrüßt, mein Name ist Nomi.\n\nIch habe gerade das Rezept bemerkt, das Ihr aufgehoben habt und... nun, ich kenne mich auch ein wenig mit dem Kochen aus.\n\nLeider bin ich im Kämpfen weniger begabt und dies ist ein sehr gefährlicher Ort. Ihr dagegen seid ganz offensichtlich <ein anerkannter/eine anerkannte:c> {class}.\n\nSucht mich in Dalaran auf. Vielleicht können wir zusammenarbeiten!", sourceObjective = "Sucht Nomi in Dalaran auf.", completion = "{class}! Ich hatte darauf gehofft, dass Ihr zurückkommen würdet.\n\nHier, werft einen Blick auf einige der Rezepte und Gerichte, an denen ich gearbeitet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[40989] = { id = 40989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Souschef", description = "{name}? <Meister/Meisterin>, seid Ihr das?\n\nErkennt Ihr mich denn nicht? Ich bin's, Nomi! Wir haben doch in Pandaria zusammen gekocht! Also genau genommen habt Ihr gekocht und ich habe gelernt. Ich war doch nur ein kleiner Junge damals.\n\nBin ich froh, Euch zu sehen!\n\nIch bin auf dem Rückweg in die Küchen von Dalaran. Besucht mich doch dort einmal. Vielleicht können wir zusammenarbeiten!", sourceObjective = "Sucht Nomi in Dalaran auf.", completion = "Meister {name}! Ich wusste, dass Ihr kommen würdet.\n\nHier, werft einen Blick auf einige der Rezepte und Gerichte, an denen ich gearbeitet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[40990] = { id = 40990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gute Rezeptliste", description = "Ich habe das Abenteurerleben ausprobiert, aber das ist nichts für mich. Meine wahre Leidenschaft ist das Kochen: die Hitze des Herdes, das Brutzeln des Specks... das ist einfach das Beste.\n\nLasst mich Euch helfen, {name}. Wenn Ihr mir ein paar Rezepte bringt, kann ich sie hier in Dalaran vielleicht noch verbessern.\n\nWir würden ein tolles Team abgeben. Was meint Ihr?", sourceObjective = "Erlernt 6 Kochrezepte von Legion.", completion = "Ihr seid wirklich erstaunlich, Meister {name}.\n\nWollen wir nun mit der Arbeit beginnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[40991] = { id = 40991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Küchenexperimente", description = "Ich kann zwar kochen, aber ich kann nicht wirklich jagen... und angeln schon mal gar nicht.\n\nAber wenn Ihr mir die Zutaten bringt, werde ich sie verwenden, um neue Rezepte auszuprobieren.\n\nWir können ja mit den paar Fischen anfangen, die ich mir zusammenschnorren konnte. Ihr findet sie in dem Fass an der Rückseite der Küche.", sourceObjective = "Holt 5 von Nomis Silbermakrelen und bringt sie ihm, damit er damit experimentieren kann.", progress = "Makrelen sind nichts Besonderes, aber sie füllen immerhin den Magen.", completion = "Geschafft! Mithilfe dieser Technik können wir gedörrte Makrelenstreifen viel effizienter zubereiten.\n\nIch bin mir sicher, dass wir noch viel mehr lernen können. Wenn Ihr mir mehr Zutaten bringt, werde ich den Ofen gar nicht kalt werden lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40994] = { id = 40994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die richtigen Werkzeuge", description = "Die Klingen, die Ihr jetzt tragt, gehören zu den mächtigsten auf ganz Azeroth. Doch wir müssen dem Feind immer zwei Schritte voraus bleiben. Mit jedem verstreichenden Moment wächst seine Armee weiter an. Und mit diesen Waffen seid Ihr ein attraktives Ziel für feindliche Meuchelmörder.\n\nSprecht mit Marin Noggenfogger in der Schatzkammer der Ungekrönten nebenan. Er hat vor Kurzem ein Projekt abgeschlossen, das Ihr hochinteressant finden werdet.", sourceObjective = "Sprecht mit Marin Noggenfogger in der Halle der Schatten.", completion = "Also, was kann ich heute für Euch tun, Meister {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[40995] = { id = 40995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kraft injizieren", description = "Mehr Kraft wollt Ihr? Ja, da seid Ihr bei mir genau richtig!\n\nWir haben kürzlich ein seltenes Gift von einer unbekannten Insel in den südlichen Meeren in die Hände bekommen und so viel wie möglich davon eingelagert.\n\nMeine Jungs haben dann eine Apparatur gebaut, um das Gift in Waffen zu injizieren. Aber bis wir die entsprechenden Effekte besser beherrschen, geht das nur in geringen Dosen.\n\nNun, wie auch immer, wir haben es in dem Sicherheitsbereich da drüben eingeschlossen. Ihr dürft es gern verwenden, Schatten {name}, aber das kostet natürlich.", sourceObjective = "Überzeugt Marin Noggenfogger davon, Euch den Schmelztiegel der Ungekrönten verwenden zu lassen, und benutzt ihn, um Eurem Artefakt mehr Macht zu verleihen.", progress = "Ganz wie meine liebe Mutter immer sagte: Mit Geld lässt sich alles regeln.", completion = "Hey, nicht der Rede wert. Ich bin immer hier, wenn Ihr etwas braucht!\n\nAber das mit der Rede meine ich wortwörtlich. Kein Wort davon, denn es gibt hier Leute, die alles dafür tun würden, an das Zeug ranzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40996] = { id = 40996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delegierung", description = "Wenn ich Euch einen Rat bezüglich der vor Euch liegenden Prüfungen und Strapazen geben darf: Zögert nicht, die vielen Ressourcen der Ungekrönten für Eure Vorhaben zu nutzen.\n\nIn der Schenke neben diesem Raum gibt es ein Schwarzes Brett, mithilfe dessen wir die Anstrengungen unserer Untergebenen koordinieren.\n\nSucht Nikki an diesem Brett auf. Sie kann Euch eine Einführung geben.", sourceObjective = "Sprecht mit Nikki der Tratsche.", completion = "Ich weiß nichts über niemanden.\n\nAch, wem will ich denn was vormachen? Ich weiß alles über alle! Wie geht's denn, Schatten {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[40997] = { id = 40997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tödliche Effizienz", description = "Ich habe gehört, dass Ihr runter zu den Verheerten Inseln wollt. Stimmt das?\n\nGleich nachdem wir von dem Ort gehört hatten, haben wir alle Bücher, Folianten und Papiere gefilzt, die wir in die Hände bekommen konnten. Wir haben einen ziemlich umfassenden Bericht zusammengestellt. Ihr solltet da mal reinschauen.\n\nUnd hier ist übrigens unser Schwarzes Brett, wo die Ungekrönten ihre magischen Geschäfte betreiben. Hier könnt Ihr ein Kopfgeld auf einen König aussetzen, eine Belohnung für Teufelsseide ausloben oder was immer Euch sonst noch einfällt. Eure Agenten erledigen dann die Arbeit für Euch.", sourceObjective = "Wählt Euren ersten Angriffspunkt auf den Verheerten Inseln aus.", completion = "Eine gute Wahl! Wir haben haufenweise Informationen über diesen Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[41000] = { id = 41000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bürde von König Forgalash", description = "Diese Meereshexe hat die Wahrheit gesagt.\n\nIch habe selbst mehrmals beobachtet, wie sich die Gezeitenherrin mit König Forgalash unterhalten hat.\n\nTötet Forgalash und schleppt zum Beweis seines Ablebens den Bug von seiner Schulter zu Fjolrik.\n\nWir treffen uns dann später im Zentrum von Jandvik. Ich muss mich erst ein wenig am Feuer aufwärmen.", sourceObjective = "Holt Euch Forgalashs Schiffsbug von König Forgalash in Forgalashs Höhle.", sourceObjectiveStatus = "unverified-source-field" }
quests[41001] = { id = 41001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtung der Sashj'tar", description = "Die Truppen der Sashj'tar wurden zwar dezimiert, aber die Gezeitenherrin hat die kampfstärksten Naga um sich geschart.\n\nJetzt ist die Zeit gekommen, einen vernichtenden Schlag gegen die Sashj'tar zu landen.\n\nWenn wir sie jetzt besiegen, können wir diese Bedrohung vielleicht endgültig beenden und Jandvik retten.", sourceObjective = "Tötet 12 Naga der Sashj'tar in den Ruinen der Sashj'tar.", completion = "Vielleicht hat diese Bedrohung durch die Naga jetzt ein Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[41002] = { id = 41002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Waffe der Horde", description = "Ich scheine Euren Wert zunächst unterschätzt zu haben.\n\nIm kommenden Krieg werden wir die Hilfe Euresgleichen brauchen. Ich will diese Dämonen bis ans Ende von Azeroth jagen, und Ihr werdet der Pfeil sein, den ich auf sie loslasse.\n\nSagt Euren Illidari in Orgrimmar, dass sie sich bereit machen sollen, der Horde zu dienen.\n\nAber seid gewarnt, denn Eure Art hat einst dem Verräter gedient. Wenn Ihr mich verratet, wird es auf der ganzen Welt keinen Ort geben, der Euch vor meiner Rache schützen kann.", sourceObjective = "Meldet Euch bei Elthyn Da'rai im Lager der Illidari in Orgrimmar.", completion = "Ihr habt dem neuen Kriegshäuptling bewiesen, dass auf uns Verlass ist. Gute Arbeit.\n\nUm die Legion zu vernichten, benötigen wir die gesamte Stärke der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[41003] = { id = 41003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geschenk des Kaisers", description = "Ah, Sheilun, der legendäre, von unserem letzten Kaiser verwendete Stab. Wenn diese Waffe der Legion in die Klauen fiele, könnten sie den ganzen Kontinent mit unvorstellbarem Schrecken überziehen. Wir müssen sie aufhalten!\n\nWenn Ihr so schnell wie möglich zur Terrasse gelangen wollt, solltet Ihr Euch direkt zum Festland bringen lassen. Tak-Tak, ein Drachenmeister der Ho-zen, müsste sich irgendwo westlich des Tempels herumtreiben. Ihr solltet ihn unverzüglich aufsuchen.", sourceObjective = "Bergt Sheilun, den Stab der Nebel, auf der Terrasse des Endlosen Frühlings. Sprecht mit Tak-Tak, um direkt zur Terrasse zu fliegen.", progress = "Die Terrasse des Endlosen Frühlings gilt den {race} auf dem Kontinent als äußerst heiliger Ort. Ich hoffe, Ihr konntet die Verderbnis von dort fernhalten. Von Pandaria wurde schon genug zerstört, als Garrosh Höllschrei das Land in ein Schlachtfeld verwandelt hat.", completion = "Unglaublich. Das ist tatsächlich der Stab, mit dessen Hilfe der Kaiser Pandaria vor Urzeiten in Nebel gehüllt hat!\n\nPasst gut auf diesen Stab auf, {name}. Er wird Euch das Leben retten und wahrscheinlich auch das all Eurer Freunde...", sourceObjectiveStatus = "unverified-source-field" }
quests[41006] = { id = 41006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Typ muss sterben" }
quests[41008] = { id = 41008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Jägern", description = "Ich spüre Eure Verwicklung in das Netz des Schicksals. Ihr seid untrennbar mit der uralten Nachtelfe verbunden, die Euch auf diese Reise geschickt hat.\n\nIch kann Euch zurück in die Himmelsstadt bringen. Von dort aus müsst Ihr nach Verbündeten für den Kampf gegen die unersättliche Dunkelheit suchen.\n\nViel Glück im Kampf, {name}. Möge Euch Fangklaue gut dienen.", sourceObjective = "Kehrt zum Laden \"Die Weiten des Jägers\" in Dalaran zurück und sprecht dort mit Emmarel Schattenwächter.", sourceObjectiveStatus = "unverified-source-field" }
quests[41009] = { id = 41009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Jägern", description = "Jetzt, wo Titanenblitz in Eurem Besitz ist, solltet Ihr etwas mehr über die Nachtelfe erfahren, der wir diese Reise zu verdanken haben.\n\nKann gut sein, dass sie wieder im Laden \"Die Weiten des Jägers\" zu finden ist, wo Ihr sie getroffen habt. Wer immer diese Emmarel Schattenwächter auch ist... ich verwette meinen Bart darauf, dass sie im Krieg gegen die Legion einen Unterschied machen wird!\n\nDanke noch mal für den Spaß, {name}. Ruft mich einfach, wenn Ihr mich je braucht!", sourceObjective = "Begebt Euch zum Laden \"Die Weiten des Jägers\" in Dalaran und sprecht dort mit Emmarel Schattenwächter.", completion = "Es gibt noch viel zu tun, edler {class}. Aber zuvor wollt Ihr sicher wissen, wer ich bin und warum ich an Euch herangetreten bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[41010] = { id = 41010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischraserei", description = "{name}!\n\n<keuch, keuch>\n\nDas müsst Ihr Euch ansehen! Die Fische... sie springen einfach überall herum!\n\nIrgendetwas lässt sie vor der Küste von Val'sharah in Raserei verfallen.\n\nDas ist die perfekte Gelegenheit zum Angeln!\n\nIch habe ein Boot da unten. Schnappt Euch Eure Angelrute, dann bringe ich Euch da raus!", sourceObjective = "Folgt Nat Pagle zum Dämmernden Riff und holt so viele Fische wie möglich aus dem Wasser.", completion = "Was um alles in der Welt habt Ihr mir da angeschleppt?! Nat hat Euch gesagt, Ihr sollt mich bitten, DAS HIER in eine Angelrute zu verwandeln?\n\n<Marcia nimmt Euch den abgetrennten Köder ab. Als sie ihn in die Nähe der Perle hält, fängt er an, mit ihr im Einklang zu schwingen.>\n\nDas ist ja interessant. Zwischen der Perle und dem hier scheint es eine Verbindung zu geben. Es könnte zu interessanten Ergebnissen führen, das hier in eine Angelrute zu verwandeln...", sourceObjectiveStatus = "unverified-source-field" }
quests[41011] = { id = 41011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umbralsplitterrituale" }
quests[41012] = { id = 41012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kirin Tor Showdown Seen" }
quests[41013] = { id = 41013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finsterbrularena" }
quests[41014] = { id = 41014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Straße der Wut" }
quests[41015] = { id = 41015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artefaktexperten gesucht", description = "Eure Waffe ist wahrlich mächtig, aber deshalb dürfen wir uns nicht einfach auf unseren Lorbeeren ausruhen. Glücklicherweise habe ich eine überaus angesehene Zwergenexpertin der Handwerks- und Verzauberkunst für uns gewinnen können.\n\nIch möchte, dass Ihr mit Betild sprecht, um zu sehen, ob sie Eure Waffe nicht mit noch mehr Macht erfüllen kann.", sourceObjective = "Sprecht mit Betild Tiefenamboss im Netherlichttempel.", completion = "Ah, da seid Ihr ja. Lasst mich mal diese unvergleichliche Waffe sehen, die Ihr herumschwingt wie einen Spazierstock aus dem Souvenirladen!", sourceObjectiveStatus = "unverified-source-field" }
quests[41016] = { id = 41016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BC TL" }
quests[41017] = { id = 41017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verleiht Eurem Artefakt mehr Macht", description = "Da Ihr offensichtlich fest entschlossen seid, das Ding jedem Dämon auf Azeroth auf den Kopf zu hauen, wollen wir doch versuchen, es noch etwas aufzupeppen. Mit Saa'ras Hilfe hab ich diesen Draeneialtar hier in einen Fokussierungsapparat umwandeln können und... ach, überspringen wir den theoretischen Teil lieber, oder?\n\nSteckt das Ding einfach da rein und probiert es aus!", sourceObjective = "Verwendet den Altar des Lichts und Schattens.", completion = "Na, wenn das nicht hübsch aussieht!\n\nIhr werdet aber erst lernen müssen, mit dem Ding vernünftig umzugehen. Dann können wir weiter daran rumpfuschen, was natürlich VIEL besser ist, als es in einem Museum auszustellen und seinen historischen Wert entsprechend zu würdigen...\n\nIhr solltet zu Alonsus zurückkehren, der guckt uns schon so merkwürdig an.", sourceObjectiveStatus = "unverified-source-field" }
quests[41019] = { id = 41019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktionen auf Azeroth", description = "Lasst mich Euch die Schlachtkarte zeigen. Dank einer Draeneikonstruktion und der Magie der Naaru verfügen wir jetzt über ein Fenster zu den Verheerten Inseln! Damit könnt Ihr Strategien ausarbeiten, Eure Agenten auf Missionen entsenden und Euer erstes Operationsgebiet auswählen.\n\nWerft einen Blick darauf und sagt mir einfach, wo wir beginnen sollen!", sourceObjective = "Verwendet die Schlachtkarte, um Euer erstes Operationsgebiet auszuwählen.", completion = "Eine ausgezeichnete Wahl! Wir werden unser Bestes geben, Eure Bemühungen auf den Verheerten Inseln zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41024] = { id = 41024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgesang der Toten" }
quests[41025] = { id = 41025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederauferstehung der Gefallenen" }
quests[41026] = { id = 41026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Schatten" }
quests[41027] = { id = 41027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letzter Atemzug", description = "<Auf dem von Meereswasser durchnässten Pergament befindet sich eine hastig hingekritzelte Notiz.>\n\nAn den unbekannten Finder:\n\nBevor ich aus Suramar verstoßen wurde, war ich ein Meisteralchemist. Zu meiner Zeit habe ich unzählige Tränke und Elixiere für die Nachtgeborenen entwickelt.\n\nAber all dies spielte keine Rolle mehr, als die Legion kam.\n\nBevor ich dem Hunger zum Opfer falle, wollte ich noch ein letztes Gebräu erschaffen, um meiner Liebe zum Meer Ausdruck zu verleihen.\n\nTrinkt es und erkundet mir zu Ehren die unendlichen Tiefen.Ihr erlernt:", sourceObjective = "Trinkt das seltsame Gebräu des Alchemisten der Nachtsüchtigen in der Azurwindbucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[41028] = { id = 41028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energieversorgung", description = "In dieser Station sind dringende Reparaturarbeiten vonnöten. Der Energiekreislauf ist zusammengebrochen und um ihn instand zu setzen, müssen wir die Siegel in der Zentralkammer wieder aufladen.\n\nFür jedes Siegel wird je ein hoch- und ein niederenergetischer Strom benötigt. Ihr müsst die beiden Ströme gleichzeitig auf ein Siegel lenken und es dann aktivieren.\n\nIch? Ich werde das Ganze beobachten. Schließlich seid Ihr mir als Aushilfskraft zugeteilt worden.", sourceObjective = "Ladet das Mondsiegel, das Sternensiegel, das Tiersiegel und das Elfensiegel in der Leystation Tel'anor auf.", completion = "Ich muss zugeben, dass Ihr mich beeindruckt habt. Vielleicht seid Ihr ja doch zu etwas nütze.", sourceObjectiveStatus = "unverified-source-field" }
quests[41029] = { id = 41029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest for Latosius Challenge 2" }
quests[41030] = { id = 41030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufladung der Siegel", description = "Das glatte, viereckige Siegel ist viel schwerer, als man bei seinem Anblick glauben würde.\n\nIhr verspürt ein leichtes Kribbeln, während es in Eurer Handfläche liegt. Dies ist eindeutig ein Gegenstand von konzentrierter und reiner Macht.\n\nEin solch vorteilhaftes Objekt sollte besser nicht den Nachtgeborenen überlassen werden.", sourceObjective = "Sammelt 7 Siegel der Mondwache.", progress = "Was ist das?", completion = "Es war weise von Euch, dies unseren Feinden abzunehmen, {class}. Ich glaube, dass man Euch vertrauen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[41031] = { id = 41031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Wohle des Volkes", description = "Wir haben ein Problem, <mein Freund/meine Liebe>.\n\nDas Viertel auf der anderen Seite des Kanals ist nicht gerade reich. Seit der Ankunft der Dämonen ist es abgeriegelt. Ich habe die Schreie derjenigen gehört, denen nun die Nahrung fehlt.\n\nNehmt diesen Weinschlauch. Sucht einen Arkweinbrunnen und bedient Euch.\n\nFindet die Leidenden und bietet ihnen einen Schluck an. Unter diesen Umständen ist das alles, was wir für sie tun können.\n\nDabei dürft Ihr nicht gesehen werden, {name}. Das nimmt sonst kein gutes Ende.", sourceObjective = "Sucht einen Arkweinbrunnen, an dem Ihr Euren leeren Arkweintrinkschlauch befüllen könnt, und bietet Nachtgeborenen unter Manaentzug dann Arkwein an.", sourceObjectiveStatus = "unverified-source-field" }
quests[41032] = { id = 41032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Magiesuchern Einhalt gebieten", description = "Es haben sich hier schon jede Menge Nachtgeborene zusammengefunden. Als wäre das noch nicht besorgniserregend genug, trifft jetzt sogar weitere Verstärkung ein.\n\nIch habe gesehen, wie sie große Portale nach Suramar geöffnet haben.\n\nDurch diese Portale haben sie ihre Konstrukte hindurchgeschleust. Sie sind gegen den größten Teil meiner Magie immun und stellen damit ein Hindernis dar, das uns davon abhält, uns den anderen wieder anzuschließen.\n\nFindet diese Portale und schließt davon so viele Ihr könnt, um uns etwas Zeit zu verschaffen.", sourceObjective = "Schließt 3 Magiesucherportale.", completion = "Ja! Ich spüre, wie ihre Zauber nachlassen. Schon bald werde ich wieder bei Thalrenus sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[41033] = { id = 41033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück nach Mardum", description = "Das Tor ist voll funktionsfähig, {name}. Uhh, ich zittere schon vor Aufregung!\n\nLasst Jace und die anderen wissen, dass wir Eure Ankunft gespannt erwarten. Es gibt so viel zu tun und nur so wenig Zeit.\n\nIhr werdet uns doch sicher beistehen, nicht wahr?", sourceObjective = "Durchschreitet das Illidaritor, um in Mardum an Bord der Teufelshammer zu gehen.", completion = "Dieser Ort ist wie für den Krieg geschaffen. Genau, was wir brauchen, um Chancengleichheit zu erzielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41034] = { id = 41034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserschlacht", description = "Jetzt gibt es keinen Ort mehr, an dem sich die Sashj'tar vor Euch verstecken können, {name}.\n\nMit einem direkten Angriff in ihren eigenen Gewässern werden sie nicht rechnen. Dies ist eine perfekte Gelegenheit, um ihre Kommandanten auszuschalten.\n\nTrefft mich in Jandvik, nachdem Ihr sie getötet habt.", sourceObjective = "Tötet Raz'jira, Malt'his und Kel'tariss in der Azurwindbucht.", completion = "Es befinden sich Meeresriesen in der Bucht?!\n\nIhr müsst unverzüglich Toryl darüber informieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[41035] = { id = 41035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelssturms Bitte", description = "Ihr kennt mich vielleicht nicht, aber dennoch muss ich um Eure Hilfe bitten, {name}.\n\nBitte trefft mich am Violetten Tor, dann werde ich Euch alles erklären.\n\nUnd bitte beeilt Euch, denn ich fürchte, wir haben nicht viel Zeit.", sourceObjective = "Trefft Euch mit Meryl Teufelssturm am Violetten Tor in Dalaran.", completion = "Ich war ein Narr. Ich dachte, ich könnte Kathra'natir ein für alle Mal verbannen, aber stattdessen hat sich der Schreckenslord befreit...\n\nIn den Jahren, die er in meinem Körper gefangen war, muss er auch Zugriff auf meine Geheimnisse gehabt haben... wie jene des Rates von Tirisfal.\n\nDer Schaden, den er mit diesem Wissen anrichten könnte, ist unermesslich. Wir müssen ihn aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[41036] = { id = 41036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis des Schreckenslords", description = "Kathra'natir hat sich meiner Kontrolle entzogen, aber ich kenne seinen nächsten Schritt.\n\nEr sucht nach einem uralten Relikt, nach der Schmiede des Wächters, mit deren Hilfe der Rat von Tirisfal jahrhundertelang den Wächter mit Macht erfüllt hat. Die Schmiede wurde verborgen und ihr Standort ist nur dem Rat selbst bekannt.\n\nUnd jetzt weiß es auch der Schreckenslord.\n\nWir müssen uns zur Violetten Festung begeben. Ich kann nur hoffen, dass wir nicht zu spät kommen.", sourceObjective = "Besiegt Kathra'natir in der Violetten Festung.", progress = "Wir müssen uns beeilen!", completion = "In längst vergangenen Zeiten wandte sich der Rat von Tirisfal in Abwesenheit eines Wächters an die Tirisgarde, die Beschützer von Dalaran, um an seiner Stelle zu kämpfen.\n\nEs ist jetzt offensichtlich, dass wir die Halle der Tirisgarde erneut errichten müssen, um dieser neuen Bedrohung zu begegnen.\n\nUnd dafür benötige ich Eure Hilfe. Zunächst einmal müsst Ihr wissen, wie Ihr zu dieser Halle kommt. Ich werde es Euch zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41037] = { id = 41037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungezügelte Macht", description = "Unsere Truppen haben diese Zitadelle zwar in Eurer Abwesenheit tapfer verteidigt, aber den Großteil ihrer Ressourcen konnten wir nicht nutzen. Die Teufelshammer kann nur durch jemanden vollständig aktiviert werden, der das Mal eines Legionslords trägt.\n\nGlücklicherweise findet sich dieses Mal auf Euren Klingen. Aktiviert mit ihrer Hilfe die Teufelshammer und zeigt unseren Truppen Eure unendliche Macht!", sourceObjective = "Aktiviert die Teufelshammer und sammelt Eure Illidaritruppen.", progress = "Ja?", completion = "Die Teufelshammer ist voll einsatzfähig.", sourceObjectiveStatus = "unverified-source-field" }
quests[41038] = { id = 41038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Metmeisterin", description = "Das Sturmgebräu wird von einer legendären Vrykulbraumeisterin namens Melba hergestellt. Hier ist der Standort ihrer Brauerei an der nördlichen Küste von Sturmheim.\n\nWenn wir sie überreden könnten, ihr Geheimrezept preiszugeben, hätten wir einen deutlichen Vorteil gegenüber dem Feind.\n\nAlso, wie steht es um Eure Überzeugungskünste, <Großmeister/Großmeisterin>?", sourceObjective = "Sprecht mit Aegira in Sturmheim.", progress = "Was wollt Ihr?", completion = "Meine Meisterin war sehr beliebt und sie hat ihr Wissen an mich weitergegeben.\n\nAber das Rezept für das Sturmgebräu, ihr am besten gehütetes Geheimnis, wurde gestohlen, bevor sie es mir beibringen konnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[41039] = { id = 41039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlenes Wissen", description = "Morjirn, der Oberbraumeister des Wellenskornklans, ist im Besitz des Sturmgebräurezeptes.\n\nIch allein war nie schlagkräftig genug, um seine Festung anzugreifen. Aber wir beide zusammen könnten Rache für meine gefallene Meisterin nehmen. Ich freue mich schon darauf, das Rezept den kalten, toten Fingern Morjirns zu entwinden.\n\nUnd wir sollten auch noch eine Kostprobe von dem Sturmgebräu nehmen, wenn wir schon einmal dort sind. Ich würde gern wissen, ob er auch nur annähernd so gut brauen konnte wie meine Meisterin.", sourceObjective = "Probiert das saure Sturmgebräu, das milde Sturmgebräu sowie das lodernde Sturmgebräu und tötet Morjirn, um ihm das Sturmgebräurezept abzunehmen.", progress = "Habt Ihr das Rezept?", completion = "Als ich diese Notizen zum letzten Mal gesehen habe, war ich noch ein kleines Kind.\n\nJetzt verstehe ich das meiste davon.\n\nEs wird nicht einfach sein, alle Zutaten zu besorgen, aber ich glaube, wir können es schaffen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[41040] = { id = 41040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Die Braumeisterin", description = "Ich habe einen neuen Durchbruch bei Melbas Sturmgebräurezept erzielt.\n\nWir müssen einen speziellen Kessel verwenden, der im Besitz von Odyn selbst ist.\n\nUnd dieser Kessel befindet sich direkt in den Hallen der Tapferkeit.\n\nEs gibt nur eine Möglichkeit, diesen erhabenen Ort zu betreten. Dazu benötigt man die Gunst des Sturmgottes.\n\nIhr müsst einen Weg in die Hallen der Krieger finden. Vielleicht solltet Ihr ein paar Verbündete für diese Unternehmung rekrutieren, {name}.", sourceObjective = "Sprecht mit Melba in den Hallen der Tapferkeit.", completion = "Hallo, Champion.\n\nIch habe Euch bereits aus der Ferne beobachtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[41042] = { id = 41042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Chomper" }
quests[41045] = { id = 41045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matron Moves" }
quests[41047] = { id = 41047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voller Kraft", description = "Mit dieser Waffe in Euren Händen könnt Ihr der Legion einen mächtigen Schlag versetzen... aber so leicht geben sich die Dämonen nicht geschlagen. Genau wie Eure Kampftaktiken muss sich auch Eure Waffe weiterentwickeln.\n\nDieser Altar vor Euch ist erfüllt von uralter Magie und den Fertigkeiten sowie der Beharrlichkeit vieler Generationen von Jägern.\n\nWenn Ihr Eure Waffe darauf ablegt, wird sich mit der Zeit ihr ganzes Potenzial entfalten.", sourceObjective = "Verwendet den Altar, um Eure Artefaktwaffe mit einer neuen Kraft zu versehen.", completion = "Das ist wundervoll! Die zunehmende Kraft Eures Artefakts wird die Dämonenarmee in Angst und Schrecken versetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[41048] = { id = 41048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Treasure 003 - Jandvik - twh" }
