quests[41051] = { id = 41051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Treasure 006 - Jandvik - twh" }
quests[41052] = { id = 41052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Bitte", description = "{name}, seit unserem Verlust an der Verheerten Küste war Saurfang einfach nicht mehr derselbe. Obwohl er gute Arbeit als Anführer geleistet hat und viele ihm dort erlegen sind, hat er unsere Niederlage nicht richtig verkraftet.\n\nIch fürchte, er ist entschlossen, zur Verheerten Küste zurückzukehren. Könntet Ihr mit ihm sprechen?", sourceObjective = "Trefft Euch mit Hochfürst Saurfang an Krasus' Landeplatz.", progress = "Werdet Ihr helfen?", completion = "Sehr gut, lasst uns herausfinden, was uns an dieser verhängnisvollen Küste erwartet.\n\nZumindest ein Haufen toter Dämonen! Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[41053] = { id = 41053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altar der Ewigen Jagd", description = "Nachdem Ihr Jäger aus ganz Azeroth zusammengerufen habt, ist es jetzt an der Zeit, Eure Aufmerksamkeit der Schlacht gegen die Brennende Legion zu widmen.\n\nIn der Volltrefferhütte befindet sich der Altar der Ewigen Jagd. Ich glaube, dass Ihr dieses antike, mit uralter Magie erfüllte Relikt dazu verwenden könnt, Eure Waffe mit noch größerer Macht auszustatten.\n\nGeht in die Hütte und sprecht mit Altarhüter Biehn, damit er Euch zeigt, wie Ihr vorgehen müsst.", sourceObjective = "Sprecht mit Altarhüter Biehn in der Volltrefferhütte.", completion = "Seid gegrüßt, {name}! Es wird mir eine Ehre sein, Euch mit Eurem Artefakt zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41054] = { id = 41054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Liebe", description = "Malfurion, mein Geliebter...\n\nIch sah ihn in einer Vision. Er war zornig... dann litt er plötzlich Qualen. Und nun kann mein Geist ihn nicht mehr erreichen.\n\n{race}, ich weiß, wir haben wenig Grund, einander zu vertrauen, doch ich werde Eure Hilfe nicht ablehnen.\n\nWenn Euch die Unantastbarkeit dieser Welt etwas bedeutet, werdet Ihr mich begleiten.", sourceObjective = "Sprecht mit Tyrande Wisperwind in der Sternensangzuflucht.", completion = "Betet, dass mein Mann all das hier lebend übersteht, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[41055] = { id = 41055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustikale Rachegefühle" }
quests[41056] = { id = 41056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Liebe", description = "Malfurion, mein Geliebter...\n\nIch sah ihn in einer Vision. Er war zornig... dann litt er plötzlich Qualen. Und nun kann mein Geist ihn nicht mehr erreichen.\n\nEr ist stark, aber die Gräuel, die dieses Land befallen haben, zehren alles auf.\n\nIch muss ihn finden... und Ihr müsst mir helfen!\n\nNehmt Eure Sinne zusammen, {race}, und folgt mir.", sourceObjective = "Sprecht mit Tyrande Wisperwind in der Sternensangzuflucht.", completion = "Ich bete, dass es noch nicht zu spät ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[41057] = { id = 41057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustikale Rachegefühle" }
quests[41059] = { id = 41059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Odyns Kessel", description = "Eure Taten in Sturmheim zeugen von großem Mut. Ich danke Euch dafür, dass Ihr mich gerächt und meiner Schülerin Aegira geholfen habt. Ich könnte mir niemand vorstellen, der besser geeignet wäre, mein Wissen zu übernehmen.\n\nIch werde das Geheimnis meines Sturmgebräus mit Euch teilen. Die wahre Stärke des Getränks stammt von Odyns Kessel in der großen Halle gleich da vorn.\n\nIch erlaube Euch, ihn auszuleihen. Viel Glück auf Euren Reisen, {name}.", sourceObjective = "Holt Odyns Kessel aus den Hallen der Tapferkeit und besteht dann Odyns Prüfung.", progress = "Habt Ihr die Prüfungen bestanden?", completion = "Sagt mir... Sind die Hallen der Tapferkeit wirklich so großartig wie in den Erzählungen? Aber wie auch immer... Ihr habt den Kessel. Jetzt können wir mit dem Brauen beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41060] = { id = 41060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungezügelte Macht", description = "Unsere Truppen haben diese Zitadelle zwar in Eurer Abwesenheit tapfer verteidigt, aber den Großteil ihrer Ressourcen konnten wir nicht nutzen. Die Teufelshammer kann nur durch jemanden vollständig aktiviert werden, der das Mal eines Legionslords trägt.\n\nGlücklicherweise findet sich dieses Mal auf Euren Klingen. Aktiviert mit ihrer Hilfe die Teufelshammer und zeigt unseren Truppen Eure unendliche Macht!", sourceObjective = "Aktiviert die Teufelshammer und sammelt Eure Illidaritruppen.", completion = "Die Teufelshammer ist endlich unser.\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[41062] = { id = 41062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lohn des Sieges", description = "Die Teufelshammer wird uns ein angemessenes Zuhause bieten, aber was wir im Bauch des Schiffes gefunden haben, ist ein wahrer Schatz und der verdiente Lohn für unseren Feldzug.\n\nSchlachtenfürst Gaardoun und seine Aschenzungen halten Wache über unsere Beute. Lasst sie Euch von ihm zeigen!", sourceObjective = "Lasst Euch von Schlachtenfürst Gaardoun zeigen, welche Beute Eure Truppen gemacht haben.", completion = "Es ist mir eine Ehre, zu dienen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[41064] = { id = 41064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfluchte Schmiede der Nathrezim", description = "Die dunklen Meister der Legion suchen unermüdlich nach neuen Wegen und Schrecken, um uns und vor allem Euch zu vernichten.\n\nIhr müsst daher ebenfalls Eure Kräfte stärken.\n\nDie verfluchte Schmiede der Nathrezim, unser größter Beuteschatz aus der Teufelshammer, befindet sich in der Kammer da vorn. Ihr könnt sie verwenden, um Euren Klingen mehr Macht zu verleihen und einen Vorteil über den Feind zu erhalten.", sourceObjective = "Verwendet die verfluchte Schmiede der Nathrezim, um Eurem Artefakt mehr Macht zu verleihen.", completion = "Das ist wahre Macht! Ihr werdet die Armeen der Legion scharenweise auslöschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[41066] = { id = 41066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blick des Jägers", description = "{name}, ich präsentiere Euch Euren Nethertiegel. Er ist mächtiger als alles, was wir je zuvor geschaffen haben.\n\nDie Seelen hunderter getöteter Dämonen aus Mardum haben uns ausreichend Energie geliefert, um uns einen direkten Blick auf die Legion in Azeroth zu gewähren.\n\nUnd was wir bis jetzt gesehen haben, ist... zutiefst beunruhigend. Aber bitte, blickt selbst hinein und bildet Euch Euer eigenes Urteil.", sourceObjective = "Verwendet den mächtigen Nethertiegel, um einen Blick auf die Truppen der Brennenden Legion in Azeroth zu werfen.", progress = "Die Bedrohung durch die Legion ist größer, als wir dachten.", completion = "Wir dürfen die Legion nicht unterschätzen. Ich befürchte, dass sie noch mächtiger ist, als wir annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41067] = { id = 41067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit drängt", description = "Wie Ihr sehen könnt, haben wir kaum noch Zeit. Die Armeen der Legion rücken unerbittlich weiter in unsere Welt vor.\n\nKayn hat unsere besten Strategen vor der Sternenkarte versammelt, um unseren Angriffsplan zu besprechen. Auf Eure Führungsqualitäten können wir dabei unmöglich verzichten.", sourceObjective = "Sprecht mit Kayn Sonnenzorn.", completion = "<Kayn seufzt.>\n\nIch kenne diesen Gesichtsausdruck. Ich habe auch in den Tiegel geblickt und die Schrecken des Grabmals gesehen.\n\nWir müssen umgehend handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[41069] = { id = 41069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An der Spitze des Widerstands", description = "Wir müssen das Grabmal des Sargeras um jeden Preis versiegeln, sonst werden diese Dämonenfluten niemals versiegen.\n\nAber bis dahin werden wir vor Ort alles tun, um sie daran zu hindern, ihren Brückenkopf weiter auszubauen.\n\nDiese Zitadelle wurde gebaut, um die Invasionen der Legion in andere Welten vorzubereiten. Wir dagegen können ihr Navigationssystem dazu verwenden, um unseren Angriff zu planen.\n\nUnd Ihr stimmt mir wohl zu, dass niemand besser geeignet wäre, diesen Angriff anzuführen, als Ihr.", sourceObjective = "Wählt Euren ersten Angriffspunkt auf den Verheerten Inseln aus.", completion = "Sehr gut. Eure taktischen Fähigkeiten sind meinen ebenbürtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[41070] = { id = 41070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lohn des Sieges", description = "Im Zuge der Eroberung dieser Zitadelle haben wir einen Schatz erbeutet, der Euch von großem Nutzen sein könnte.\n\nGaardouns Leute da unten halten Wache über ihn. Ihr solltet ihn Euch zeigen lassen.", sourceObjective = "Lasst Euch von Schlachtenfürst Gaardoun zeigen, welche Beute Eure Truppen gemacht haben.", completion = "Es ist mir eine Ehre, zu dienen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
