quests[41084] = { id = 41084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reward: Ebonchill" }
quests[41085] = { id = 41085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Magiers", description = "Damit ist es also entschieden.\n\nDie Stärke der Tirisgarde gründet sich auf die uralten Artefakte in den Händen ihrer Champions. Eure erste Aufgabe besteht darin, ein solches Artefakt zu bergen.\n\nIm Hauptverzeichnis dieser Bibliothek sind alle dem Rat von Tirisfal bekannten Artefakte aufgelistet. Ihr werdet darin auf ein paar interessante Optionen stoßen.\n\nIch überlasse es Euch, welches Artefakt Ihr bergen möchtet.", sourceObjective = "Verwendet das Verzeichnis der Artefakte von Azeroth, um ein Artefakt auszuwählen, das Ihr bergen wollt.", completion = "Eine kluge Wahl.\n\nDamit solltet Ihr für die Jagd auf Kathra'natir gut gerüstet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[41086] = { id = 41086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine friedliche Welt", description = "Wir haben erfahren, dass die Legion auf die Verheerten Inseln vorrückt.\n\nSie greift von allen Seiten an, und wenn wir sie nicht aufhalten können, wird sie ganz Azeroth überrennen.\n\n{name}, wir brauchen Eure Hilfe jetzt mehr als je zuvor. Bitte helft jenen, die die Front verteidigen. Wir dürfen diese Schlacht einfach nicht verlieren.", sourceObjective = "Schließt 10 Weltquests ab.", completion = "Das ist ganz erstaunlich, Großmeister! Wir erhalten von allen Seiten Berichte über Euren Erfolg. Ohne Euer Eingreifen wären viele unserer Außenposten auf den Verheerten Inseln gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41087] = { id = 41087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmgebräu", description = "<Großmeister/Großmeisterin>, die Legion greift die Wandernde Insel an!\n\nWir haben Verteidiger zum Grat der Lachenden Winde entsandt, aber sie können dort nicht lange ausharren.\n\nUnsere einzige Chance ist es, das Sturmgebräu herzustellen. Chen und Aegira sind bereits zur Kammer des Raunens hinaufgegangen, aber auch sie sind schweren Angriffen ausgesetzt.\n\nSprecht mit Tak-Tak und fliegt sofort mit einem Drachen hinauf, um ihnen zu helfen!", sourceObjective = "Fliegt mit Tak-Taks Drachen hinauf zum Grat der Lachenden Winde und helft Chen Sturmbräu und Aegira dabei, das Sturmgebräu herzustellen. Erringt danach einen Sieg über die Streitkräfte der Brennenden Legion.", completion = "Ich weiß ja nicht, wie es Euch geht, Großmeister, aber ich denke, nach alldem sollten wir eine wohlverdiente Pause einlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41089] = { id = 41089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürsten der Anhöhen" }
quests[41090] = { id = 41090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürsten der Anhöhen" }
quests[41091] = { id = 41091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürsten der Anhöhen" }
quests[41092] = { id = 41092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Guards Move" }
quests[41093] = { id = 41093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Durguth" }
quests[41094] = { id = 41094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Küken der Kralle", description = "Seid gegrüßt, Küken. Möchtet Ihr Euch auch zu den Wolken aufschwingen, wie meine Kinder es tun?\n\n<Avianas Kichern klingt rau wie das Krächzen einer Krähe.>\n\nAlso schön, nehmt meinen Segen und dann werden wir ja sehen, wie gut Eure Flügel entwickelt sind.", sourceObjective = "Sprecht mit Aviana, um ihren Segen zu erhalten, und schließt dann ihre Aufgabe ab, indem ihr Smaragdkugeln einsammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[41095] = { id = 41095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichtige Ernte" }
quests[41096] = { id = 41096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit drängt", description = "Wie Ihr sehen könnt, haben wir kaum noch Zeit. Die Armeen der Legion rücken unerbittlich weiter in unsere Welt vor.\n\nAltruis hat unsere besten Strategen vor der Sternenkarte versammelt, um unseren Angriffsplan zu besprechen. Auf Eure Führungsqualitäten können wir dabei unmöglich verzichten.", sourceObjective = "Sprecht mit Altruis dem Leidenden.", completion = "<Altruis nickt wissend.>\n\nIch habe es auch gesehen.\n\nWir müssen unseren nächsten Schritt umsichtig planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41097] = { id = 41097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitter von Vorgos", description = "Laut Aussage des Wyrmzungenknechts gibt es ein Portal, durch das Ihr auf das Kommandoschiff der Brennenden Legion gelangt. Allerdings kann man das Portal nur mit den richtigen Schlüsselsplittern öffnen.\n\nDer erste Schlüsselsplitter ist im Besitz eines Ered'ruin namens Vorgos. Er lebt in der Teufelsbresche am Ende des Arkus.\n\nTötet Vorgos und platziert den Schlüsselsplitter in der richtigen Position neben dem Portal.", sourceObjective = "Sammelt den Splitter von Vorgos ein.", progress = "<Der Splitter von Vorgos pulsiert in Eurer Hand.>", completion = "<Der Splitter von Vorgos nimmt seinen Platz neben dem Portal ein. Um den Splitter herum sammelt sich Teufelsenergie an und füllt den Raum mit einer mysteriösen, dunklen Präsenz.>", sourceObjectiveStatus = "unverified-source-field" }
quests[41098] = { id = 41098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitter von Kozak", description = "Der Dämon, der die Operation in der Teufelsseelenbastion anführt, ist ein Eredar namens Azoran. Wenn wir an ihn rankommen wollen, müssen wir ein Portal öffnen, das auf das Kommandoschiff der Brennenden Legion führt.\n\nFür Azoran arbeitet ein Dämonengefängniswärter namens Kozak der Besudler.\n\nKozak verfügt über einen der Schlüsselsplitter, die man benötigt, um ein Portal zum Schiff zu öffnen. Er hält sich meistens in den Hallen der Dunkelung auf, in dem Gefängnistrakt im unteren Bereich der Teufelsseelenbastion.\n\nTötet Kozak und platziert den Schlüssel in der richtigen Position neben dem Portal.", sourceObjective = "Sammelt den Splitter von Kozak ein.", progress = "<Der Splitter von Kozak zerrt an Eurer Hand, als könne er es nicht erwarten, eingesetzt zu werden.>", completion = "<Der Splitter von Kozak nimmt seinen Platz neben dem Portal ein. Ihr spürt, wie die wirbelnde, dunkle Teufelsenergie Euch umgibt, während sie sich neben dem Portal ansammelt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[41099] = { id = 41099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An der Spitze des Widerstands", description = "Das Grabmal des Sargeras ist das primäre Einfallstor der Legion in unsere Welt. Es muss zerstört werden.\n\nDas ist keine einfache Aufgabe. Und bis wir die dafür nötigen Mittel haben, müssen wir alles tun, um diese Invasion aufzuhalten.\n\nDie Legion hat diese Zitadelle dazu verwendet, ihre Invasionen in andere Welten vorzubereiten. Wir aber können ihr Navigationssystem dazu verwenden, um unseren eigenen Angriff zu planen.\n\nNatürlich überlassen wir Euch die Ehre, den ersten Fuß auf ihr Territorium zu setzen, aber wir folgen Euch dichtauf.", sourceObjective = "Wählt Euren ersten Angriffspunkt auf den Verheerten Inseln aus.", completion = "Eine gute Wahl. Schon bald wird die Legion lernen, den Anblick der Illidari auf dem Schlachtfeld zu fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[41100] = { id = 41100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Swap Didis" }
quests[41105] = { id = 41105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwert der Könige", description = "Thoradin, der erste König der Menschen, vollbrachte viele Heldentaten. Kurz vor Ende seiner Herrschaft befand er sich auf einer persönlichen Mission und stieß dabei auf das Grab, in dem nicht nur mein Bruder Tyr, sondern auch das grausame Monster ruhte, das ihn getötet hatte. Thoradin weckte diese Bestie versehentlich und starb in seinem Bemühen, sie am Entkommen zu hindern.\n\nNur mithilfe seines Schwertes Strom'kar konnte Thoradin das Monster in Schach halten. Bergt dieses Schwert und bringt zu Ende, was Tyr und Thoradin begonnen haben. Tötet Zakajz den Verderbten.", sourceObjective = "Sucht nach Strom'kar dem Kriegsbrecher und kämpft gegen Zakajz.", progress = "Ah, Ihr seid zurückgekehrt...", completion = "Ein mächtiges Schwert! Geschmiedet vom Sohn eines Vrykul, verzaubert durch Elfenmagie und gebadet im Blut eines C'Thraxxi. Es wird Euch gute Dienste leisten, {name}. Mit seiner Hilfe werdet Ihr unsere Feinde besiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[41106] = { id = 41106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Wildnis", description = "Um die Legion zu besiegen, müssen wir schnell und unerwartet zuschlagen.\n\nWir haben einen Traumpfad entdeckt, mit dessen Hilfe wir durch den Smaragdgrünen Traum selbst reisen können. Im Traum ist es nur eine kurze Strecke, aber auf Azeroth legen wir dabei riesige Entfernungen zurück und haben sogar Zutritt nach Val'sharah, dem uralten Zuhause aller Druiden.\n\nMalfurion bereitet gerade das Ritual zur Öffnung des Traumpfads vor. Ich möchte, dass Ihr ihm Zen'tabra und Naralex zur Seite stellt.\n\nWir werden nur dann erfolgreich sein, wenn wir all unsere Kräfte bündeln.", sourceObjective = "Macht Zen'tabra und Naralex ausfindig und sorgt dafür, dass sie sich an der Ritualstätte einfinden.", progress = "Das Ritual muss unbedingt gelingen, {name}.", completion = "Gut, das Ritual wird jetzt bald beginnen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[41107] = { id = 41107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faule Äpfel", description = "Dieses Obst da drüben? Das ist nur ein müder Abklatsch von dem, was ich anbauen kann.\n\nAber diesem verfluchten Daglir ist es irgendwie gelungen, die Gunst des Hofes zu gewinnen, sodass wir uns mit mittelmäßigen Früchten zufriedengeben müssen!\n\nWir müssen Daglir dafür eine Lektion erteilen, dass er mir das Geschäft vermiest - ohne uns dabei erwischen zu lassen.\n\nAußerhalb des Schilds wächst eine violette Blume namens Schattenblüte. Wenn Ihr ein paar davon einsammeln könnt, werden wir ihn für seine Unverschämtheit zahlen lassen!", sourceObjective = "Sammelt 8 Schattenblüten ein.", progress = "Ich würde dringend anraten, Euch die Hände zu waschen, bevor Ihr irgendetwas zu Euch nehmt.", completion = "Ausgezeichnet. Das sollte für meine Zwecke genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41108] = { id = 41108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es regnet Tod", description = "Auf dem Rücken des Hippogryphen bietet sich Euch jetzt eine einzigartige Gelegenheit. Es wird Zeit, dass die Nachtgeborenen bedauern, Euch am Leben gelassen zu haben.", sourceObjective = "Tötet 50 Nachtgeborene.", sourceObjectiveStatus = "unverified-source-field" }
quests[41109] = { id = 41109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warten auf Rache", description = "Der instabile Zauberfokus brummt in Eurer Hand vor Energie. Schön vorsichtig damit!\n\nNur mit diesem Gegenstand in Eurem Besitz lassen Euch die Hippogryphen aufsteigen.", sourceObjective = "Steigt auf einen Hippogryphen auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[41110] = { id = 41110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warten auf Rache", description = "Der Hippogryph schaut Euch neugierig an und schnüffelt an Euren Händen.", sourceObjective = "Steigt auf den Hippogryphen auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[41111] = { id = 41111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es regnet Tod", description = "Mit dem Hippogryphen vor Euch bietet sich jetzt eine einzigartige Gelegenheit. Es wird Zeit, dass die Nachtgeborenen bedauern, Euch am Leben gelassen zu haben.", sourceObjective = "Tötet 50 Nachtgeborene.", sourceObjectiveStatus = "unverified-source-field" }
quests[41112] = { id = 41112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Große Akazamzarak", description = "Es gibt da einen Goblin namens Akazamzarak. Er ist ein Meister der Portale und Teleportationskünste. Aber seine Fähigkeiten sind weitgehend unbemerkt geblieben, weil er sie zumeist für billige Tricks verwendet.\n\nMan könnte ihn als so eine Art Straßenkünstler bezeichnen.\n\nZum Glück für uns tritt er gerade in den Straßen von Dalaran auf, um den ungebildeten Massen ein paar Münzen aus der Tasche zu ziehen.\n\nNehmt diesen Beutel voll Gold und versucht, ihn davon zu überzeugen, seinen Beruf zu wechseln.", sourceObjective = "Steckt den ansehnlichen Münzbeutel in Akazamzaraks Trinkgeldeimer.", completion = "Oh, ja, Ihr habt meine volle Aufmerksamkeit!\n\nIhr bietet mir also eine Vollzeitstelle an, ja? Tja, wenn die weiteren Zahlungen so ausfallen wie diese hier, dann könnten wir uns schon handelseinig werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[41113] = { id = 41113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahre Art zu reisen", description = "Portale? Teleportation? Selbstverständlich kann ich Euch dabei helfen! Wie sonst ziehe ich wohl das Kaninchen aus dem...\n\nÄh... Ich hab gar nichts gesagt.\n\nAuf jeden Fall kann ich dafür sorgen, dass Eure Magier bequem an ihren Zielort gelangen, wenn der Preis stimmt. Und ich könnte diesen Kampfmagiern sogar noch den einen oder anderen Trick beibringen. Habt Ihr schon mal ein explodierendes Kaninchen auf Euch zufliegen sehen? Das ist kein schöner Anblick!\n\nSo, und damit es losgehen kann, erschaffe ich jetzt erst mal ein Portal zu dieser Halle, von der Ihr erzählt habt.", sourceObjective = "Kehrt zu Meryl Teufelssturm in der Halle des Wächters zurück.", completion = "Ich gebe zu, dass er einigermaßen unkonventionell daherkommt, aber ich glaube, dieser Goblin ist genau, was wir brauchen, um diese neue Tirisgarde aufzustellen und auf ihre Aufgaben vorzubereiten.\n\nIch habe bereits viele fähige {class} benachrichtigt, die uns helfen könnten. Sie warten auf die Teleportation zur Halle, um sich ihren neuen Aufgaben zu widmen.\n\nWollen wir also beginnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[41114] = { id = 41114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Champions", description = "Ich spüre die Macht des Artefakts in Eurer Hand. Es ist bereits jetzt eine mächtige Waffe gegen die Legion, aber wir können noch mehr von seiner Macht freilegen.\n\nIhr müsst zur Halle des Wächters zurückkehren. Um an den Runen vorbeizugelangen, könnt Ihr die Zauberformel verwenden, die ich Euch beigebracht habe.", sourceObjective = "Teleportiert Euch zur Halle des Wächters und kehrt zu Meryl Teufelssturm zurück.", completion = "Ihr lernt schnell, {name}.\n\nIch denke, Kathra'natir wird den Tag verfluchen, an dem er Euch zu seinem Feind gemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[41115] = { id = 41115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Chen Sturmbräu", sourceObjective = "Es war mir eine Ehre, am Gipfel der Ruhe an Eurer Seite zu kämpfen, {name}. Eure Talente als Anführer bedeuten einen großen Vorteil im Kampf gegen die Legion.\n\nIch würde gerne weiter für Euch kämpfen, wenn Ihr mich als Champion in Euren Diensten akzeptiert. Zudem denke ich, dass ich dem Orden auch mit meinen Braufähigkeiten weiterhelfen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[41116] = { id = 41116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Artifacts - Shaman - Puzzle Room - Treasure - DGK" }
quests[41117] = { id = 41117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seen Thalrenus Iceblock Shenanigans" }
quests[41119] = { id = 41119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd", description = "Ihr müsst diese Jagd anführen, {name}. Ihr werdet von einer kleinen Einheit begleitet, um Varedis ein für alle Male auszuschalten.\n\nIhr müsst versuchen, unbemerkt in Varedis' Festung einzudringen. Je weniger Zeit Ihr auf Legionsterritorium verbringt, desto besser.\n\nWir treffen uns an Krasus' Landeplatz, wenn Ihr zum Aufbruch bereit seid.", sourceObjective = "Beschafft die Zwillingsklingen des Betrügers von Varedis Teufelsseele in Suramar.", completion = "Was ist mit den anderen? Sind sie...?\n\nIch verstehe. Sie haben ihr Leben nicht umsonst geopfert: Die Zwillingsklingen werden ganz sicher den Ausgang des Krieges entscheiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[41120] = { id = 41120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abmachungen treffen", description = "Erinnert Ihr Euch an Varedis? Er war einst unser Hauptausbilder im Schwarzen Tempel, aber er fiel schon früh in der Schlacht.\n\nDachten wir zumindest...\n\nKor'vas hat diesen Verräter in den Reihen der Legion ausgemacht. Er schwingt ihr vollkommen unbekannte, mit Macht durchtränkte Gleven.\n\nDie Kirin Tor haben einen Eredarfürsten in der Violetten Festung bestattet, der wissen müsste, wo sich Varedis' Operationsbasis befindet. Der Festungswächter hat sich bereit erklärt, uns Zugang zu ihm zu gewähren.\n\n<Altruis grinst.>\n\nZeit, die freundliche Diplomatiekarte auszuspielen.", sourceObjective = "Trefft Euch mit Altruis dem Leidenden vor der Violetten Festung.", completion = "Bringen wir es hinter uns. Diese Bürokraten gehen mir jetzt schon auf die Nerven.", sourceObjectiveStatus = "unverified-source-field" }
quests[41121] = { id = 41121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um jeden Preis", description = "Wir müssen unbedingt Varedis' Aufenthaltsort von dem Eredar in diesem Gefängnis erfahren. Allein der freundliche Wächter und seine Männer stehen uns hier noch im Wege.\n\nWenn es sein muss, schalten wir sie eben zusammen aus.", sourceObjective = "Verschafft Euch Zutritt zur Violetten Festung und verhört Taldath den Zerstörer, um den Aufenthaltsort des Verräters Varedis zu erfahren.", progress = "Gut gemacht.", completion = "Suramar? Das ist nur eine kurze Flugstrecke von hier entfernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[41122] = { id = 41122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingenebelt" }
quests[41123] = { id = 41123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeichen des Kunsthandwerkers", description = "Ihr da! Hättet Ihr vielleicht einen Moment?\n\nIch möchte Euch bitten, jemanden auf der Promenade zu treffen und einen Siegelring entgegenzunehmen. Ich hätte ja eigentlich meinen Lehrling schicken wollen, aber der Tölpel ist immer noch mit einer anderen, simplen Aufgabe beschäftigt.\n\nIch erwarte jede Sekunde einen Gast und ich muss ihn haben, bevor er eintrifft. Könntet Ihr mir vielleicht helfen, <mein Freund/meine Liebe>?", sourceObjective = "Bringt Lespins Siegelring in Euren Besitz.", progress = "Habt Ihr ihn?", completion = "Oh, der Magistrix sei Dank! Ich dachte schon, er wäre auf ewig verloren.\n\nIch sehe, dass der Ring schon etwas... abgenutzt ist. Ich hoffe, er hat nicht jemandem gehört, der besonders wichtig ist... oder besonders lautstark.", sourceObjectiveStatus = "unverified-source-field" }
quests[41124] = { id = 41124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wiederauferstehung der Tirisgarde", description = "Die Tirisgarde wurde neu gegründet. Jetzt ist es an der Zeit, unsere wahre Mission zu beginnen.\n\nDer Orden braucht einen Anführer. Und ich bin zwar ein erfahrener Magier, aber kein Stratege. Ihr hingegen habt Euch sowohl in der Vergangenheit als auch in der Gegenwart als fähig erwiesen.\n\nWerdet Ihr diese Herausforderung annehmen, {name}?", sourceObjective = "Lasst Euch von Meryl Teufelssturm Euren neuen Titel verleihen.", completion = "Ihr dürft Euch also jetzt \"Oberhaupt\" nennen, hm? Nicht schlecht!\n\nDie ganze Sache mit der Tirisgarde hier scheint ja ganz gut zu laufen, aber wir sollten trotzdem weitere Mitstreiter rekrutieren, wenn wir den Dämonen tatsächlich etwas Feuer unterm Hintern machen wollen.\n\nUnd zu Eurem Glück kann niemand so gut Verträge aushandeln wie ein Goblin!", sourceObjectiveStatus = "unverified-source-field" }
quests[41125] = { id = 41125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgenes Potenzial", description = "In lang zurückliegenden Zeiten wurde die Schmiede des Wächters dazu verwendet, die Macht des Rats von Tirisfal auf einen einzelnen Magier zu kanalisieren und somit einen Wächter zu erschaffen. Aber dies ist nicht ihre einzige Verwendung.\n\nSie kann auch als Quell arkaner Energie verwendet werden, um die Artefakte dieser Welt zu manipulieren und zu verstärken.\n\nMithilfe dieser Macht werden wir den Schreckenslord und die Brennende Legion besiegen. Und darum möchte ich, dass Ihr zuerst Gebrauch von ihr macht.", sourceObjective = "Verwendet die Schmiede des Wächters, um Euren ersten Artefaktbonus freizuschalten.", completion = "Euer Artefakt ist auf dem besten Wege, sein volles Potenzial zu entfalten, aber ungeachtet seiner Macht könnt Ihr dennoch die Legion nicht ganz allein besiegen.\n\nWir müssen weitere {class} für unsere Mission gewinnen. Leider könnten die Zauberschutze, die diese Halle umgeben, dabei recht hinderlich sein.\n\nIch allein kann schließlich nicht jeden einzelnen von ihnen hierherteleportieren.\n\nAber vielleicht liegt die Lösung dieses Problems ja näher, als man denken sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[41126] = { id = 41126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Vignette: Flotsam - twh" }
