quests[41136] = { id = 41136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Vignette: Har'kess - twh" }
quests[41137] = { id = 41137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturz des Königs", description = "Jetzt bleibt nur noch der Meeresriesenkönig.\n\nPlatziert unser Banner an seinem Strand, um ihn aus dem Meer zu locken. Wenn er sich zeigt, dann verwundet ihn mit dem Dreizack.\n\nAn der Küste wurde ein herrenloses Boot angespült. Damit könnt Ihr rasch zur Insel des Königs übersetzen.\n\nSeid gewappnet, {name}. Das wird kein einfacher Kampf.", sourceObjective = "Platziert das Banner von Jandvik auf der Insel des Meeresriesenkönigs, um ihn herauszulocken, und besiegt ihn dann.", sourceObjectiveStatus = "unverified-source-field" }
quests[41138] = { id = 41138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shal'Aran versorgen", description = "Mithilfe der Leylinienenergie aus Anora kann diese Kammer zum Leben erweckt werden.\n\nEs wird seine Zeit in Anspruch nehmen und wir müssen diese Aktivitäten gut vor unseren Feinden verbergen. Dies allein wird schon ein sehr kraftraubendes Unterfangen sein.\n\nZudem ist da noch die Herausforderung, Mana in dieser Form zu verwenden. Ein zu schwacher Strom bietet uns nicht genug Kraft und ein zu starker Strom würde uns pulverisieren.\n\nEs gibt also noch viel zu tun. Lasst uns jetzt die Zuleitung untersuchen.", sourceObjective = "Untersucht zusammen mit Arkanistin Valtrois die Leylinienzuleitung in Shal'Aran.", completion = "Ich werde sicher erneut Eure Hilfe benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41139] = { id = 41139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel muss hier irgendwo sein...", description = "Da freu ich mich aber, Euch zu sehen!\n\nDiesen Käfig könnt Ihr nicht einfach aufbrechen. Ihr braucht einen Schlüssel dafür!\n\nUnd jetzt denkt Ihr sicher: \"Wie konnte es der Brennenden Legion nur gelingen, einen so mächtigen Zwerg wie Angus einzusperren?\"\n\nAber keine Sorge, ich habe mich freiwillig einsperren lassen. Ich bin nämlich hier, um einen alten Kumpel rauszuholen, und das geht nur, indem ich mich hier selbst einsperren lasse!\n\nDer Schlüssel war in meiner Tasche, aber er muss herausgefallen sein...\n\nEr sollte sich hier definitiv irgendwo finden lassen.\n\nEin Teufelshund hat ihn nämlich vor einer Weile gefressen...", sourceObjective = "Sucht nach dem Schlüssel des verstärkten Käfigs.", progress = "Habt Ihr den Schlüssel gefunden?", completion = "Ihr habt den Schlüssel! Schnell, probiert mal, ob er passt...\n\nJa, das ist der richtige! Ihr habt es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[41140] = { id = 41140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für Brambley!", description = "Wir müssen Brambley finden, bevor es zu spät ist!\n\nDer alte Brambley und ich haben nämlich schon seit dem Dritten Krieg Seite an Seite gekämpft. Als wir von der Invasion der Brennenden Legion hörten, sind wir sofort zu den Verheerten Inseln aufgebrochen.\n\nWenn wir nämlich eines können, dann kämpfen!\n\nWährend des Kampfes ist Brambley zu weit vorausgestürmt und wurde dann gefangen genommen. Jetzt müssen wir ihn retten!\n\nNoch vor Kurzem habe ich ihn in einer Gefängniszelle nicht weit von hier gesehen. Gehen wir!", sourceObjective = "Sucht nach Brambley Morrison.", progress = "Habt Ihr den Schlüssel schon gefunden?", completion = "Es tut gut, endlich aus diesem widerlichen Käfig raus zu sein. Zum Dank werde ich Euch und Eurem unglaublich stark behaarten Freund gegenüber Wort halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[41141] = { id = 41141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht eines Oberhauptes", description = "Ich weiß nicht, wie es Euch geht, aber von mir aus können wir loslegen. Hier ist es ja ganz hübsch, aber irgendwie auch ganz schön langweilig.\n\nIch werde sehen, was ich tun kann, um noch ein paar Magier für Eure Gruppe zu rekrutieren. Werft doch mal einen Blick auf die Karte da. Damit könnt Ihr Eure ersten Schritte planen.", sourceObjective = "Verwendet die Späherkarte, um Eure erste Zone auszuwählen.", completion = "Also gut! Ich kann mit dem Rekrutieren und Ihr mit dem Kampf gegen die Dämonen beginnen!\n\nJa, ich weiß, ich überlasse Euch die einfachere Tätigkeit, aber dafür hat man ja schließlich Freunde, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[41142] = { id = 41142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Vignette: Khory - twh" }
quests[41143] = { id = 41143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mglrgrs unseres Grmlgrlrs", description = "Mlrg...mglrmlr...\n\nGmlrgmlr mglrml gmlrg! Mlrgrlgr!\n\n<Mrgrglilgrl zeigt auf den Pfad aus Spinnweben, der aus der Ruine hinausführt.>" }
quests[41144] = { id = 41144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Fluss" }
quests[41145] = { id = 41145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasser des Lebens" }
quests[41146] = { id = 41146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elegantes Design", description = "Amateurhafte Händler beschweren sich über Angebot und Nachfrage. Wahre Meister lösen dieses Problem auf eigene Weise.\n\nBei den letzten beiden Stücken habt Ihr großes Geschick bewiesen, aber das war ein Kinderspiel im Vergleich zur nächsten Aufgabe.\n\nEuer Ziel ist Lady Anastae und sie hat etwas sehr Wertvolles von mir: eine Vorlage für einen meisterhaft geschliffenen Edelstein.\n\nIhr müsst ihr die Vorlage unbedingt abnehmen, aber passt gut auf Euch auf: Sie ist eine Meisterin der Manipulation und wird Euch alle möglichen Lügen auftischen.", sourceObjective = "Überzeugt Lady Anastae davon, Euch den Folianten des Juwelenschleifers zu geben.", completion = "Lespin muss für seine Verbrechen bezahlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[41148] = { id = 41148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage des Mitgefühls", description = "Es gibt vieles, was Ihr noch über unsere Stadt lernen müsst.\n\nNehmen wir zum Beispiel den Arkwein: Das ist die Substanz, aus der wir die Energien des Nachtbrunnens beziehen. Ohne diese Energien verdorren und sterben wir.\n\nDie Palastlakaien haben den Arkwein rationiert, weil sie uns so kontrollieren und gefügig halten wollen.\n\nIch möchte, dass Ihr Euch um die Bedürftigen in der Nähe der Taverne kümmert. Ihr werdet schnell bemerken, welche von ihnen am dringendsten Hilfe benötigen.\n\nNehmt diese Flasche, um ihnen neues Leben einzuhauchen und ihr Leid zu mindern.", sourceObjective = "Bietet leidenden Bürgern Arkwein an.", progress = "Habt Ihr die Leidenden versorgt?", completion = "Langsam öffnen sich Eure Augen für unsere Realität. Ich kann es an Eurem Gesichtsausdruck ablesen. Das ist gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[41149] = { id = 41149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmucker Schutz", description = "<Das kleine Gerät in eleganter Nachtgeborenenbauart knistert leicht vor arkaner Energie.\n\nIn Kel'danaths Notizen steht etwas von Zauberschutzen, um die Verdorrten in Schach zu halten. Er scheint eine Art des Zauberwirkens entdeckt zu haben, die nicht ihren gewaltigen Appetit auf Magie anspricht.\n\nDiese Geräte könnten hilfreich bei Eurer Suche nach dem vermissten Arkanisten sein.>", sourceObjective = "Aktiviert 4 arkane Zauberschutze im Zinnobertal.", sourceObjectiveStatus = "unverified-source-field" }
quests[41153] = { id = 41153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revil Defeated" }
quests[41155] = { id = 41155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunklen Reiter", description = "Am Flussufer findet sich ein Kanalisationsgitter, über das man in die Tunnel gelangen kann, die unterhalb von Karazhan verlaufen. Ich habe es nie beachtet, aber vielleicht ist das der Ort, an den die Geister uns führen wollen.\n\nVielleicht haben sich die Dunklen Reiter ja die ganze Zeit direkt unter unseren Füßen aufgehalten! Kommt, lasst uns schauen, wo uns das hinführt.", sourceObjective = "Besiegt die Dunklen Reiter in den Katakomben von Karazhan und nehmt Ulthalesh an Euch.", progress = "Habt Ihr gefunden, wonach Ihr sucht, {class}?", completion = "Ich muss zwar zugeben, dass ich all dies nicht alleine zustande gebracht hätte, aber ich werde auch die Verfehlungen des heutigen Tages nicht vergessen.\n\nIhr habt jetzt, was Ihr wolltet, {class}. Es ist an der Zeit, dass Ihr geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[41156] = { id = 41156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die einstige Macht", description = "Wir haben beide unsere Ziele erreicht, <Hexenmeister/Hexenmeisterin>. Jetzt trennen sich unsere Wege und darüber bin ich sehr froh.\n\nGeht zurück zu Euren dunklen Meistern, unsere Angelegenheiten hier sind beendet.", sourceObjective = "Kehrt zu Calydus in der Schattenseite von Dalaran zurück.", completion = "Freund hat Waffe?\n\nJa, Calydus kann ihre Macht spüren!", sourceObjectiveStatus = "unverified-source-field" }
quests[41157] = { id = 41157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Studien der Verderbnis", description = "In Sturmheim lassen sich Unmengen von Artefakten aus dem Krieg der Ahnen finden: Dämonenartefakte, um genau zu sein.\n\nIch denke, diese Artefakte bieten uns Hinweise auf ihren Anführer, Sargeras. Ich hab schon einige Fragmente einer Titanenscheibe gefunden, aber wir brauchen auch die anderen Teile.\n\nIch möchte, dass Ihr ein paar Ausgrabungen in Sturmheim vornehmt, um weitere Teile zu finden und die Scheibe wieder zusammenzusetzen.", sourceObjective = "Durchsucht die Ausgrabungsstätten in Sturmheim und bringt Brann 200 Fragmente aus dem Krieg der Ahnen zurück.", progress = "Es ist ein Wunder, dass die Gegend trotz der vielen vergrabenen Dämonenartefakte so lebendig ist.", completion = "<Brann nimmt die Fragmente entgegen und beginnt, sie zusammenzusetzen.>\n\nJa, das sind ganz sicher Teile der Titanenscheibe. Aber Ihr habt noch etwas anderes gefunden.\n\nHier seht Euch das mal an!", sourceObjectiveStatus = "unverified-source-field" }
quests[41158] = { id = 41158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmente der Fjorde", description = "{name}, habt Ihr vielleicht mein Kassenbuch irgendwo gesehen? Ich scheine es verlegt zu haben, als ich diese Kanopenkrüge verstaut habe.\n\nAch... Schon gut. Aber Brann Bronzebart hat nach Euch gefragt. Er setzt gerade seine Forschungen in Sturmheim fort.\n\nSucht ihn dort auf und sagt ihm, dass ich immer noch auf diese auf Haut geschriebenen Chroniken warte, die er gefunden hat.", sourceObjective = "Sucht Brann Bronzebart in Sturmheim auf.", completion = "Ich bin ganz nah dran, ein weiteres Teil dieser Titanenscheibe zu finden, und könnte Eure scharfen Augen gut dabei brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41159] = { id = 41159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausschlussprinzip", description = "Bei so vielen Ausgrabungsstellen, an denen man Fragmente findet, wird es langsam etwas unübersichtlich, wo man noch weitere Teile der Titanenscheibe finden könnte.\n\nAber ich habe schon einen Plan: Wenn Ihr ein paar Gegenden nach Teilen der Scheibe absuchen könnt, grenzen wir damit die verbleibenden Orte in Sturmheim ein.\n\nIch nehme mir eine Gegend vor und Ihr die andere. Kommt dann wieder her, wenn Ihr etwas gefunden habt.", sourceObjective = "Führt Ausgrabungen in Sturmheim durch, bis Ihr einen Teil der Titanenscheibe gefunden habt.", completion = "Sind Euch da draußen beim Graben diese Wichtel begegnet? Diese verdammten Dämonen wollen mich einfach nicht in Ruhe lassen!\n\nAber egal... Wenn Ihr die Scheibe an diesen Orten nicht gefunden habt, gibt es noch eine letzte Möglichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[41160] = { id = 41160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erde zu Erde", description = "Der Erde entspringt Kraft und diese Kraft kann zu mächtigen Waffen geformt werden.\n\nIhr seht aus wie jemand, der mehr über die Erschaffung solcher Waffen erfahren möchte.\n\nAuf diesem sterbenden Planeten gibt es noch immer Wesen, die jene Kraft in sich tragen. Bringt mir ihre Kerne und ich werde Euch im Austausch dafür das Wissen lehren, nach dem Ihr sucht.", sourceObjective = "Sucht für Lunelli nach einem Kardinalsteinkern, einem Kardinalerdkern und einem Kardinallavakern. Bringt die Steine zu ihr nach Shattrath, wenn Ihr sie alle zusammen habt.", progress = "Es gibt aber auch jene, die diese Kerne zu mehr gebrauchen als nur dem Schmiedehandwerk. Nehmt Euch vor solchen Wesen in Acht.", completion = "Es scheint, als ob die Erde stattdessen vor EURER Macht erzittert hat. Gut gemacht, Champion.\n\nHier ist Eure Belohnung im Austausch gegen die Kerne. Wie abgemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[41161] = { id = 41161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Regen...", description = "Oh hallo, {name}. Ich kann Euch sagen, dieser Laden kann einen wirklich in den Wahnsinn treiben. Man findet hier einfach nichts wieder.\n\nDa fällt mir ein... Brann Bronzebart hat nach Euch gefragt. Er ist in Azsuna und sucht nach weiteren Teilen von was auch immer.\n\nUnd wo sind jetzt bloß diese Zinnkelche...?", sourceObjective = "Sucht Brann in Azsuna auf.", completion = "Ich bin dicht dran, {name}. Ich kann es förmlich spüren!", sourceObjectiveStatus = "unverified-source-field" }
quests[41162] = { id = 41162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...In die Traufe", description = "Ich habe etwas gefunden, {name}. Nun, eigentlich sogar mehrere Dinge.\n\nAls Erstes habe ich einen uralten Text über einen Dämon gefunden, der die Kraft der Titanenscheibe, nach der ich suche, beherrschte.\n\nUnd dann habe ich ein Gerät gefunden, mit dem man ihn tatsächlich heraufbeschwören kann! Allerdings scheinen da ein paar Teile zu fehlen.\n\nIch bin mir sicher, dass wir diese Teile finden, wenn wir uns noch weiter in Azsuna umschauen.", sourceObjective = "Untersucht Ausgrabungsstätten in Azsuna, sucht nach 10 verschollenen Teilen des infernalischen Geräts und bringt sie dann zu Brann zurück.", progress = "Soweit ich das beurteilen kann, brauchen wir nur sieben oder acht Teile...", completion = "Ja, jetzt haben wir alle zusammen, mein Junge. Ich setz das nur schnell zusammen und dann werden wir ja sehen, was passiert...", sourceObjectiveStatus = "unverified-source-field" }
quests[41163] = { id = 41163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringer der Apokalypse", description = "So, ich habe jetzt das Gerät wieder zusammensetzen können.\n\nIch werde es einfach einschalten, wenn Ihr so weit seid, und dann lassen wir uns mal überraschen!", sourceObjective = "Sprecht mit Brann, wenn Ihr bereit seid, das Gerät einzuschalten.", completion = "Tja, das war ein bisschen... unaufregend. Aber zumindest haben wir ein weiteres Teil der Titanenscheibe!", sourceObjectiveStatus = "unverified-source-field" }
quests[41164] = { id = 41164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schritt näher", description = "{name}! Ich hab gerade gehört, dass dieser verrückte Zwerg, Brann Bronzebart, sich entschlossen hat, in Suramar Jagd auf diese Scheibe zu machen, die ihm so wichtig ist.\n\nBei allem, was gerade passiert, ist das also der ungeeignetste Ort für eine solche Expedition.\n\nAuf jeden Fall könnte er Eure Hilfe brauchen.", sourceObjective = "Sucht Brann in Suramar auf.", completion = "Hier stinkt es überall nach diesen Dämonen. Aber hier sind auch überall Hinweise auf den Fundort von einem Teil dieser Titanenscheibe!", sourceObjectiveStatus = "unverified-source-field" }
quests[41165] = { id = 41165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Entschlüsselung der Dämonologie", description = "Ich habe etwas gefunden, das wie ein Fragment eines Schlüssels aussieht. Wenn wir die anderen Teile finden, könnte ich ihn sicher wieder zusammensetzen.\n\nDann müssen wir nur noch herausfinden, was man damit öffnen kann. Ich weiß auch schon wie.\n\nIch habe einige der Artefakte untersucht, die ich hier draußen gefunden habe und sie scheinen auf eine verborgene Kammer hinzuweisen.\n\nWenn ich noch mehr dieser Artefakte studieren könnte, ließe sich die Lage dieser Kammer herausfinden.", sourceObjective = "Verwandelt Artefakte in 5 restaurierte Artefakte, sucht 5 Bruchstücke des Kammerschlüssels und bringt sie Brann.", progress = "Was macht die Suche?", completion = "Ich glaube langsam, dass Ihr genauso viel Talent für die Archäologie habt wie ich. Aber werdet jetzt nicht gleich übermütig, mein Junge.\n\n<Brann kichert und untersucht die Artefakte, die Ihr ihm gebracht habt.>\n\nJa, genau! Ich weiß jetzt, wo die Kammer ist. Und wenn ich den Schlüssel wieder zusammengesetzt habe, kann es losgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41166] = { id = 41166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Geheimnisse", description = "Ich habe den Schlüssel zusammengesetzt, also können wir jetzt die Kammer öffnen.\n\nTrefft mich dort, wenn Ihr es einrichten könnt. Dann werden wir das Geheimnis im Inneren lüften!", sourceObjective = "Trefft Brann am Eingang zur geheimen Kammer. Sobald Ihr drin seid, solltet Ihr zur Sicherheit dicht bei Brann bleiben.", progress = "Nichts geht über ein gutes Abenteuer!", completion = "Ein Teil der Titanenscheibe und ein Krug mit Blut. Kein Wunder, dass die Elfen diesen Ort abgeriegelt haben.\n\nIch nehme mir das Scheibenteil. Ihr könnt von mir aus das Blut haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[41167] = { id = 41167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflische Fragmente", description = "Brann Bronzebart hat mich darum gebeten, ihm weitere Vermessungsausrüstung zu bringen, aber ich habe keine Zeit dafür.\n\nWäret Ihr so nett, ihm diese Kiste zu bringen, {name}? Ich wäre Euch wirklich sehr verbunden.", sourceObjective = "Bringt die Kiste mit Vermessungsausrüstung zu Brann in Val'sharah.\n\nBereitgestellter Gegenstand:", completion = "Ist das meine Ausrüstung? Danke, {name}!\n\nBloß gut, dass Ihr da seid. Hier ist es wirklich unheimlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[41168] = { id = 41168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die purpurnen Hügel Eredaths", description = "So, mit der neuen Ausrüstung können wir uns frisch ans Werk machen.\n\nIch hab hier etwas gefunden, was Euch interessieren dürfte: eine Seite aus einem Buch über die Welt von Argus. Es handelt allerdings von der Zeit, bevor die Dämonen es zerstört haben.\n\nAuf jeden Fall habe ich die Erfahrung gemacht, dass dort, wo man ein Teil findet, meist noch mehr davon auftaucht.\n\nSchaut Euch in Val'sharah um, ob Ihr noch mehr Seiten findet, und bringt sie mir dann. Und nehmt die Seite mit, die ich gefunden habe, damit Ihr wisst, wonach Ihr suchen müsst.", sourceObjective = "Sucht nach den fehlenden Seiten aus \"Die purpurnen Hügel Eredaths\" und stellt sie dann zu dem ursprünglichen Buch zusammen. Bringt das fertiggestellte Buch dann zu Brann.", progress = "Ich kann es kaum erwarten, den Rest der Geschichte zu lesen.", completion = "<Brann überfliegt das zusammengestellte Buch.>\n\nUnd wo ist das letzte Kapitel?", sourceObjectiveStatus = "unverified-source-field" }
quests[41169] = { id = 41169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Durch den Nebel", description = "Kaum zu glauben, dass nach all Euren Mühen immer noch ein Kapitel fehlt!\n\nIch wette, dass diese Satyrn es in die Hände bekommen und irgendwo hingebracht haben, wo es niemand findet.\n\nIch hörte von einem finsteren Ort, den sie das Finsterherzdickicht nennen. Dort sollen sich die Stärksten der Satyrn aufhalten.\n\nIch kann mir vorstellen, dass Ihr es dort finden könntet.", sourceObjective = "Beschafft das letzte Kapitel aus \"Die purpurnen Hügel Eredaths\".", progress = "Eigentlich sollte niemand gezwungen sein, in eine Welt voller Alpträume zu reisen.", completion = "Was?! Ihr habt das fehlende Kapitel UND einen Teil meiner Titanenscheibe gefunden?!\n\nHeute ist ein richtiger Festtag. Ich überlasse Euch das Buch. Ihr könnt mir dann ja das Ende der Geschichte erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41170] = { id = 41170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufarbeitung eines Reliktes", description = "Sehr gut! Jetzt haben wir alle Teile zusammen und ich kann die Scheibe endlich wieder zusammensetzen!", sourceObjective = "Schaut Brann dabei zu, wie er die Titanenscheibe wieder zusammensetzt.", completion = "Jetzt haben wir schon so viel Zeit damit verbracht und es fehlt immer noch ein Teil!\n\nBei dieser Aufgabe scheinen sich die Götter gegen mich verschworen zu haben, {name}.\n\nAber die Arbeit muss ja weitergehen! Und hier ist noch etwas für all die harte Arbeit, die Ihr für mich erledigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[41171] = { id = 41171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Archäologische Akademie", description = "Tae'thelan von der Archäologischen Akademie hat mich gebeten, ihnen jemanden zu schicken, der ihnen bei ihrer Arbeit in Azsuna hilft.\n\nUnd da Ihr nun mal rein zufällig hier aufgetaucht seid, könntet Ihr das ja vielleicht übernehmen, {name}.\n\nAber ich muss zurück an die Arbeit, weil ich ja schließlich alles allein machen muss.\n\n<Dariness seufzt.>", sourceObjective = "Sucht Tae'thelan Blutwächter in Azsuna auf.", completion = "Ich dachte eigentlich an Archäologen, nicht an Abenteurer. Aber vielleicht seid Ihr ja beides.\n\nAlso, beginnen wir mit der Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[41172] = { id = 41172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Widerhall meiner Vorfahren", description = "In diesem Land verbergen sich viele Geheimnisse und Artefakte aus längst vergangenen Zeiten.\n\nSoweit ich es abschätzen kann, befindet sich hier ganz in der Nähe ein Artefakt von großer Macht. Ich muss aber den Fundort noch weiter eingrenzen.\n\nIch möchte, dass Ihr weitere Artefakte ausgrabt und daraus Schlüsse zieht. Kommt und berichtet mir, wenn Ihr etwas gelernt habt, was uns weiterhelfen könnte.", sourceObjective = "Schließt 25 Archäologieprojekte der Hochgeborenen ab.", completion = "<Tae'thelan hört sich Euren Bericht aufmerksam an.>\n\nSehr interessant. Wenn das alles wahr ist, dann glaube ich zu wissen, wo sich das Artefakt befindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[41173] = { id = 41173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Licht der Hoffnung", description = "Ich habe den Fundort des Artefakts auf Eurer Karte markiert. Das ist eine sehr lebensfeindliche Umgebung, darum möchte ich, dass Ihr danach sucht.\n\nBringt es zu mir, wenn Ihr es geborgen habt, damit ich seine Macht untersuchen kann.", sourceObjective = "Begebt Euch zu dem von Tae'thelan auf Eurer Karte eingetragenen Ort und sucht dort nach dem Artefakt.", progress = "Vielleicht können wir mithilfe dieses Artefakts das Kriegsglück auf unsere Seite zwingen.", completion = "Lasst mich mal sehen, was Ihr da gefunden habt.\n\n<Tae'thelan sieht sich das Artefakt einen Moment lang an und seufzt dann vernehmlich.>\n\nNutzlos. Das ist nur ein einfacher Sternenfeldgenerator. Wahrscheinlich stammt er aus irgendeiner Akademie vor dem Krieg.\n\nIhr könnt ihn behalten, {name}. Ich habe keine Verwendung dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[41174] = { id = 41174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr Gewicht in Gold", description = "{name}, wenn Ihr eine Kiste schwarzer Trilobiten wäret, wo würde ich Euch wohl hingepackt haben?\n\n<Dariness beginnt, im Laden herumzusuchen.>\n\nOh, da fällt mir wieder ein: Tae'thelan möchte mit Euch sprechen. Er hat irgendetwas in Suramar zu erledigen und benötigt Eure Hilfe.", sourceObjective = "Sucht Tae'thelan in Suramar auf.", completion = "Schön, Euch zu sehen, {name}.\n\nIch hatte gehofft, dass die Elfen hier etwas... aufgeschlossener wären, wenn es darum geht, ihre Artefakte zu untersuchen, aber das war leider ein Irrtum.\n\nUnd jetzt kommt Ihr ins Spiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[41175] = { id = 41175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einer Elfenkönigin würdig", description = "Die Nachtgeborenen haben ihren Schild deaktiviert, sodass wir in ihre Stadt eindringen und ihre Geheimnisse erforschen können.\n\nEines dieser Geheimnisse ist eine Krone von unermesslicher Macht.\n\nIch möchte, dass Ihr diese Krone findet und mir berichtet, was man damit anstellen kann.", sourceObjective = "Kämpft Euch durch Suramar hindurch bis in die Kammer mit der Krone. Untersucht die Krone und erstattet dann Tae'thelan Bericht.", completion = "Ihr habt sie gefunden?\n\n<Tae'thelan hört sich Euren Bericht über die verschwundenen Edelsteine aufmerksam an.>\n\nIch verstehe. Dann war die Krone nur eine Art Behältnis und die Edelsteine bergen die wahre Macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[41176] = { id = 41176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche in den Trümmern", description = "Dann ist wohl vollkommen klar, was wir jetzt tun müssen: nämlich diese Edelsteine finden.\n\nSie müssen noch irgendwo hier in Suramar sein. Wir sollten gleich mit der Suche anfangen.\n\nIch werde die Suche von hier aus koordinieren, während Ihr und meine Assistenten Ausschau nach ihnen halten.", sourceObjective = "Sucht die verschiedenen Gegenden um Suramar herum ab, bis Ihr die 6 verschwundenen Edelsteine der Krone gefunden habt.", progress = "Wie sieht es mit der Suche nach den Edelsteinen aus?", completion = "<Tae'thelan nimmt die Edelsteine von Euch entgegen und sieht sie sich genau an.>\n\nVielleicht haben sie einmal eine Kraft geborgen, aber jetzt ist nichts mehr davon übrig. Jetzt sind es nur noch hübsche Edelsteine.\n\nHier, nehmt sie. Betrachtet sie als Bezahlung für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41177] = { id = 41177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinarchäologie", description = "Ich weiß nicht, ob Ihr davon wisst, aber die Archäologische Akademie soll die Goblins damit beauftragt haben, ihr bei der Suche nach Artefakten in diesem Land zu helfen.\n\nIch möchte, dass Ihr herausfindet, ob an diesem Gerücht etwas dran ist und dieses Vorhaben zu Ergebnissen geführt hat.", sourceObjective = "Sucht Tae'thelan in Val'sharah auf.", completion = "{name}, Ihr kommt gerade rechtzeitig, um eine neue Methode auszuprobieren, die ich erarbeitet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[41178] = { id = 41178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Resultate", description = "Ihr habt ja vielleicht schon gehört, dass ich mit den Goblins zusammen an einer neuen Methode zur Bergung von Artefakten arbeite.\n\nUnd wie das bei den Goblins eben so ist, geht es dabei natürlich um Sprengstoff.\n\nWir haben hier im Lager schon ein paar Tests gemacht, aber es wäre sehr hilfreich, wenn Ihr draußen einen Praxistest durchführen könntet.\n\nIch habe den Standort von ein paar besonders problematischen Ausgrabungsstätten auf Eurer Karte markiert.", sourceObjective = "Verwendet den Goblinsprengstoff, um 500 Artefaktfragmente aus ihrer geologischen Gefangenschaft zu befreien.", progress = "In der Theorie sollte das Material, das das Artefakt umschließt, durch eine bestimmte Menge Schießpulver nur leicht erschüttert werden.", completion = "Hat es funktioniert? Das ist ja großartig!\n\nDamit werden wir unsere Effizienz verzehnfachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[41179] = { id = 41179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was einst verloren war", description = "Das erinnert mich daran, dass ich eine Karte zu einer Kammer gefunden habe, in der sich vielleicht etwas Wertvolles verbirgt.\n\nEs scheinen keine besonderen Mächte an sie gebunden zu sein, darum überlasse ich Euch die Sache.\n\nHier, nehmt noch ein paar Sprengladungen mit. Das beschleunigt die Sache vielleicht.", sourceObjective = "Begebt Euch zum auf der Karte eingetragenen Ort und bergt das Artefakt. Verwendet das Dynamit, um das Artefakt freizulegen.", completion = "<In der kleinen Truhe findet Ihr eine noch kleinere Truhe, deren Deckel mit einem Rabenkopf verziert wurde.>", sourceObjectiveStatus = "unverified-source-field" }
quests[41180] = { id = 41180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unaussprechliche Macht", description = "{name}, ich habe die Nachricht erhalten, dass der Oberste Prüfer Euch dringend sehen möchte.\n\nEr hat endlich etwas sehr, SEHR Mächtiges gefunden und möchte, dass Ihr ihm helft, es zu bergen.\n\nPasst gut auf Euch auf da unten, {name}. Tae'thelan kann mitunter etwas fanatisch werden, wenn es um Artefakte geht, die besondere Energien bergen.", sourceObjective = "Sucht Tae'thelan Blutwächter in Suramar auf.", completion = "Das ist alles sehr aufregend, {name}. Und Ihr genießt einen Platz in der ersten Reihe dieser Sensation.", sourceObjectiveStatus = "unverified-source-field" }
quests[41181] = { id = 41181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingrenzen", description = "Ich hatte recht damit, dass es hier mächtige Objekte der Nachtgeborenen gibt. Ich habe einen uralten Text mit Hinweisen auf einen Gegenstand gefunden, den sie Kugel von Sciallax nennen.\n\nWenn ich mich an die Schriften über den Krieg der Ahnen richtig erinnere, war Sciallax ein Dämonenfürst, der nach Suramar kam und den Elfen damals ein mächtiges Artefakt im Gegenzug für ihre Dienste in der Legion anbot.\n\nIch habe den genauen Standort noch nicht entdeckt, aber vielleicht führen uns ja ein paar Ausgrabungen zu einer Antwort.", sourceObjective = "Führt in Suramar Untersuchungen durch, um 10 verwitterte Hochgeborenenschriftrollen zu finden.", progress = "Wir müssen dieses Artefakt um jeden Preis finden!", completion = "Ihr habt den Ort gefunden? Dann müssen wir uns beeilen.\n\nLasst uns aufbrechen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[41182] = { id = 41182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enthüllt die Kugel von Sciallax", description = "Wir müssen uns beeilen, bevor die Nachtgeborenen bemerken, was wir vorhaben.\n\nIch bringe die Goblins mit, falls wir unterwegs auf ein paar Hindernisse stoßen.\n\nIch habe den Eingang zur Kammer mit der Kugel auf Eurer Karte markiert.\n\nTrefft mich dort so bald wie möglich, damit wir uns dieses Artefakt sichern können.", sourceObjective = "Trefft Euch mit Tae'thelan Blutwächter am Eingang zur Kammer mit der Kugel von Sciallax. Wenn Ihr drinnen seid, müsst Ihr die Sprengladungen an der Einfassung anbringen und das Artefakt bergen.", progress = "Also?", completion = "OH, NEIN! Wie konnte das nur geschehen? Wir waren so nah dran.\n\nDie Sprengladungen waren zu groß. Diese verdammten Goblins haben alles ruiniert!\n\nJetzt sind von diesem Objekt mit unvorstellbarer Kraft nur noch eine Handvoll Splitter übrig.\n\nSucht Euch eins davon aus, {name}. Den Rest würde ich gern behalten und untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41183] = { id = 41183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akademische Erkundungen", description = "{name}, schön Euch zu sehen! Was haltet Ihr jetzt von meinem Laden? Nicht schlecht für eine einzelne Person, oder?\n\nDa fällt mir ein: Der Oberste Prüfer Tae'thelan führt hier in Azsuna ein paar Ausgrabungen durch und möchte, dass Ihr ihn aufsucht.\n\nSo wie ich ihn kenne, glaubt er wieder einmal, ein mächtiges Artefakt gefunden zu haben, das die Welt verändern kann.", sourceObjective = "Sucht Tae'thelan in Azsuna auf.", completion = "Hallo, {name}. Schön, dass Ihr kommen konntet.\n\nIch habe etwas gefunden, das unser beider Interessen dienlich sein könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[41184] = { id = 41184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewährte Mittel", description = "Meine Erfahrungen haben mich erkennen lassen, dass die alten Methoden immer noch die besten sind, und zwar aus gutem Grund. Ich habe jetzt genug von alternativen Ausgrabungstechniken und will mich auf das Wesentliche konzentrieren.\n\nUnd so glaube ich, ein neues, mächtiges Artefakt gefunden zu haben, für dessen Bergung ich wortwörtlich alles tun will, was erforderlich ist.\n\nIch habe nämlich ein Fragment entdeckt, das eine Schlüsselform darstellen könnte. Und jetzt brauche ich nur noch die anderen Teile.", sourceObjective = "Sucht nach 15 azsunianischen Schlüsselformteilen und bringt sie dann zu Tae'thelan.", progress = "Habt Ihr weitere Teile gefunden?", completion = "Ja, ich glaube, das sind alle.\n\n<Tae'thelan setzt die Schlüsselform vorsichtig zusammen.>\n\nUnd jetzt müssen wir nur noch ein paar neue Schlüssel gießen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41185] = { id = 41185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlüssel zum Erfolg", description = "Ich möchte, dass Ihr die Schlüsselform zu einem Schmied in Dalaran bringt. Ich glaube, sein Name ist Alard.\n\nEr soll Euch dabei helfen, einen neuen Schlüsselsatz anzufertigen.\n\nIch habe auf der Rückseite der Form eine Inschrift gefunden, die Auskunft über die Verwendung der Schlüssel geben könnte. Ich werde hierbleiben und den Text in der Zwischenzeit zu übersetzen versuchen.", sourceObjective = "Bringt die Schlüsselform zu Alard Schmied in Dalaran, damit er Euch hilft, einen neuen Schlüsselsatz anzufertigen. Kehrt dann mit den neuen Schlüsseln zu Tae'thelan zurück.", progress = "Der Schlüssel ist auf jeden Fall für irgendetwas hier in Azsuna vorgesehen.", completion = "Dies ist gar kein echter Schlüssel, sondern ein Gerät, um zu einem Ort namens Akademie von Nar'thalas zu reisen.\n\nDiese Akademie war früher eine ruhmreiche Stätte des arkanen Wissens der Nachtelfen, aber sie ist schon vor langer Zeit zerstört worden.\n\nDer Schlüssel ist wertlos. Ihr könnt ihn behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[41186] = { id = 41186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichte des Hochbergs", description = "Also, mal sehen... eins... zwei... drei... Oh, hallo {name}. Tut mir leid, ich habe Euch gar nicht bemerkt.\n\nEs war in letzter Zeit ziemlich hektisch hier. Ich könnte wirklich Hilfe brauchen.\n\nAber ich habe da etwas für Euch: Eine Archäologiekollegin namens Lessah hat um Hilfe bei ihrer Arbeit am Hochberg gebeten.\n\nIch dachte, Ihr wäret genau <der/die> Richtige dafür.", sourceObjective = "Sucht Lessah am Hochberg auf.", completion = "Schön, Euch zu sehen, {name}. Ich hoffe, Ihr habt genauso viel Interesse an den Tauren wie ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[41187] = { id = 41187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschungsnachhilfe", description = "Der Grund, warum ich um Hilfe gebeten habe, ist, dass ich zurzeit Probleme habe, selbst zu forschen und gleichzeitig meinen Forschungsassistenten auszubilden.\n\nIch hoffe, dass Ihr ihm wieder etwas in die Spur helfen und die Forschungsarbeit näherbringen könnt.\n\nSprecht bitte einfach mit ihm, wenn Ihr so weit seid.", sourceObjective = "Führt zusammen mit Luron 20 erfolgreiche Forschungsaufträge aus.", completion = "Danke für Eure Hilfe, {name}. Vielleicht könnt Ihr mir ja jetzt bei meiner Forschung helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41188] = { id = 41188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Hort: Fehlgeleitet", description = "Ich habe mich mit der Geschichte von Huln Hochberg, dem legendären Krieger aus dem Krieg der Ahnen, dem dieser Berg seinen Namen verdankt, beschäftigt.\n\nAngeblich wurden ein paar seiner persönlichen Dinge nach seinem Tode hierhergebracht und gingen dann im Lauf der Zeit verloren.\n\nNach ein paar Ausgrabungen habe ich jetzt wohl die Fundstelle eines seiner Artefakte gefunden. Es befindet sich in Neltharions Hort.\n\nIch bin nicht mit Euren Kampffähigkeiten gesegnet, {name}. Würdet Ihr das Artefakt für mich bergen?", sourceObjective = "Begebt Euch zu Neltharions Hort und bergt das uralte Hochbergartefakt.", progress = "Wenn ich alle Hinweise richtig verstanden habe, könnten wir eine von Hulns Waffen ausfindig machen.", completion = "Das ist... keine von Hulns Waffen. Es sieht vielmehr aus wie der Speer von Rethu, einem legendären Taurenminenarbeiter.\n\nDieses Artefakt interessiert mich nicht, {name}. Ihr könnt es behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[41189] = { id = 41189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Spur", description = "{name}, Lessah am Hochberg hat nach Euch gefragt.\n\nSie hat offenbar einen Hinweis darauf, wo sich ein antikes Rüstungsteil von Huln Hochberg finden lässt.\n\nSucht sie da draußen auf, wenn Ihr es einrichten könnt.", sourceObjective = "Sucht Lessah am Hochberg auf.", completion = "Dieses Land hat noch so viel mehr zu bieten, als ich dachte, {name}. Und jetzt hört zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[41190] = { id = 41190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallaugen", description = "Ich habe die Höhlen hier erforscht und dabei viele uralte Inschriften gefunden.\n\nDie interessantesten davon befanden sich bei den Resonanzkristallen, wo die Drogbar sich aufgehalten haben. Leider sind die Drogbar den Tauren hier nicht gerade wohlgesonnen, sodass ich mit meinen Forschungen nicht weiterkomme.\n\nIch kann mir aber vorstellen, dass Ihr mit den Drogbar umzugehen versteht.\n\nIch möchte, dass Ihr meine Forschungen fortführt und so viel wie möglich über Huln herausfindet.", sourceObjective = "Interagiert mit den zwei verschiedenen Resonanzsteinen am Hochberg. Für jeden Stein benötigt Ihr 3 Hochbergritualsteine, um ihn aktivieren zu können.", completion = "<Lessah hört sich aufmerksam die von Euch entdeckten Geschichten an.>\n\nWenn das alles wahr ist, dann handelt es sich bei dem Gegenstand, hinter dem ich her bin, um Hulns Halskette.", sourceObjectiveStatus = "unverified-source-field" }
quests[41191] = { id = 41191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drogbartäuschung", description = "Anhand meiner Forschungen und Eurer Informationen konnte ich herausfinden, wo die Halskette zu finden ist.\n\nSie befindet sich tief im Innern einer Drogbarhöhle und ich wette, sie werden sie nicht freiwillig rausrücken, {name}.\n\nIch möchte, dass Ihr ihnen diese Halskette abnehmt... um jeden Preis.", sourceObjective = "Holt Euch die uralte Halskette und bringt sie Lessah.", progress = "Wenn man doch nur mit den Drogbar reden könnte.", completion = "<Lessah untersucht die Halskette.>\n\nAber wie ist das denn möglich?! Laut all meiner Forschungen sollte diese Kette Huln gehört haben.\n\nTut mir leid, {name}... Aber diese Halskette haben die Drogbar selbst angefertigt. Ich werde sie Euch zurückgeben. Macht damit, was Ihr wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[41192] = { id = 41192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem rechten Pfad", description = "Dieser neue Laden nimmt langsam Form an. Aber es ist immer noch so viel zu organisieren.\n\n{name}, Lessah hat Euch gebeten, zum Hochberg zu kommen. Sie erwähnte irgendein Tier... einen Elch vielleicht?\n\nIch weiß nicht genau, was sie vorhat, aber vielleicht könnt Ihr ja mal nach ihr sehen.", sourceObjective = "Sucht Lessah am Hochberg auf.", completion = "{name}, ich habe tatsächlich etwas aus dem näheren Umfeld von Huln gefunden.\n\nIch glaube, das ist ein Knochen von Huln Hochbergs Tierbegleiter Eche'ro höchstselbst!", sourceObjectiveStatus = "unverified-source-field" }
quests[41193] = { id = 41193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Ruhe der Gebeine", description = "Wenn ich ein solches Knochenfragment vollkommen zufällig gefunden habe, dann müssten ja Eche'ros Knochen auf dem ganzen Hochberg verstreut liegen.\n\nWir müssen seine Überreste finden und ihm ein ordentliches Begräbnis gewähren.\n\nOh, tut mir leid, aber vielleicht wisst Ihr das ja gar nicht... Eche'ro war Huln Hochbergs Reittier und Gefährte.\n\nEr verdient die gleiche Ehre wie einst Huln.", sourceObjective = "Sucht nach 600 Knochenfragmenten von Eche'ro und bringt sie zu Lessah am Hochberg zurück. Schaut Euch dann Lessahs Begräbniszeremonie an.", progress = "Wir müssen dafür sorgen, dass seine Überreste ehrenvoll behandelt werden.", completion = "Was für eine Ehre, {name}. Es gibt wohl keine größere Belohnung für Euch als zu wissen, dass Eche'ros Geist höchstselbst Euch in der Not zur Hilfe eilen wird.\n\nUnd für mich natürlich, Zeuge von Hulns erhabener Präsenz zu werden! Ich werde ihn und sein ruhmreiches Erbe auch weiterhin studieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[41194] = { id = 41194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remulos Tracker" }
